// 数据文件：自 evolution-chain-viz.html 拆分（2026-08-16 扩展准备）
const nodeDetails = {"side:R0":{"question":"已知三角形两边为 2、3，求第三边 x 的范围。","analysis":"已知三角形两边为 2、3，设第三边为 x ｜ —1分 ｜ 【得分理由：正确设元】\n由三角形三边关系：任意两边之差小于第三边、两边之和大于第三边，得 |3−2|<x<3+2 ｜ —1分 ｜ 【得分理由：列出三边关系不等式】\n即 1<x<5 ｜ —1分 ｜ 【得分理由：化简得范围】\n答：第三边 x 的取值范围为 1<x<5 ｜ —1分 ｜ 【得分理由：完整作答】\n（进化点：这是“求边长范围”的最原始母题。）"},"side:E01":{"question":"锐角三角形三边为 2、3、x，求 x 的范围。","analysis":"由三角形三边关系：|3−2|<x<3+2，得 1<x<5 ｜ —1分 ｜ 【得分理由：先由三边关系确定大范围】\n按锐角三角形分类：若 x 为最大边，则 x²<2²+3²=13，得 x<√13 ｜ —1分 ｜ 【得分理由：最大边为 x 时用锐角条件】\n若 3 为最大边，则 9<4+x²，得 x²>5，即 x>√5 ｜ —1分 ｜ 【得分理由：最大边为 3 时用锐角条件】\n综合 1<x<5、x<√13、x>√5 ｜ —1分 ｜ 【得分理由：取各条件交集】\n∴ √5<x<√13 ｜ —1分 ｜ 【得分理由：写出最终范围】"},"side:E07":{"question":"锐角三角形中，b 是 1/2、2 的等比中项，c 是 1、5 的等差中项，求 a 的取值范围。","analysis":"由等比中项定义：b²=1/2×2=1，且 b>0，得 b=1 ｜ —1分 ｜ 【得分理由：正确求等比中项】\n由等差中项定义：c=(1+5)/2=3 ｜ —1分 ｜ 【得分理由：正确求等差中项】\n问题转化为锐角三角形三边 1、3、a；由三边关系得 2<a<4 ｜ —1分 ｜ 【得分理由：还原为三边问题并求三边关系范围】\n锐角条件：a 最大时 a²<1²+3²=10，得 a<√10；3 最大时 9<1+a²，得 a>2√2 ｜ —1分 ｜ 【得分理由：分最大边用锐角条件】\n综合得 2√2<a<√10 ｜ —1分 ｜ 【得分理由：写出最终范围】\n（进化点：条件从“直接给边”变成“用中项关系表达”，入口多了翻译一步。）"},"side:E05a":{"question":"三边为 a、a+1、a+2 的锐角三角形，求 a 的范围。","analysis":"由三角形三边关系：a+(a+1)>a+2，得 a>1 ｜ —1分 ｜ 【得分理由：三边关系求 a 的下界】\n三边中最大边为 a+2，锐角三角形中最大边所对角为锐角 ｜ —1分 ｜ 【得分理由：确定最大边与锐角对应】\n由余弦定理推论：(a+2)²<a²+(a+1)²，展开得 a²−2a−3>0 ｜ —1分 ｜ 【得分理由：用锐角条件列不等式】\n因式分解 (a−3)(a+1)>0，得 a>3 或 a<−1；结合 a>1 取 a>3 ｜ —1分 ｜ 【得分理由：解二次不等式并取交集】\n∴ a>3 ｜ —1分 ｜ 【得分理由：写出最终范围】\n（进化点：这一步只做“具体→参数”，还没有变成钝角。）"},"side:E05":{"question":"三边为 a、a+1、a+2 的三角形为钝角三角形，求 a 的范围。","analysis":"由三角形三边关系：a+(a+1)>a+2，得 a>1 ｜ —1分 ｜ 【得分理由：三边关系求 a 的下界】\n三边中最大边为 a+2，钝角三角形中最大边所对角为钝角 ｜ —1分 ｜ 【得分理由：确定最大边与钝角对应】\n由余弦定理推论：(a+2)²>a²+(a+1)²，展开得 a²−2a−3<0 ｜ —1分 ｜ 【得分理由：用钝角条件列不等式】\n因式分解 (a−3)(a+1)<0，解得 −1<a<3 ｜ —1分 ｜ 【得分理由：解二次不等式】\n结合 a>1，得 1<a<3 ｜ —1分 ｜ 【得分理由：与三边关系取交集】"},"ssa:R0":{"question":"在△ABC中，b=10，A=30°，求边 a 的取值范围。","analysis":"由正弦定理 a/sinA=b/sinB，得 a=b·sinA/sinB ｜ —1分 ｜ 【得分理由：正确用正弦定理建立关系】\n代入 b=10、A=30°：a=10×sin30°/sinB=5/sinB ｜ —1分 ｜ 【得分理由：代入数据计算】\nB 为三角形内角，故 sinB∈(0,1] ｜ —1分 ｜ 【得分理由：确定 sinB 的值域】\n由 0<sinB≤1 得 1/sinB≥1，故 a=5/sinB≥5 ｜ —1分 ｜ 【得分理由：由值域求 a 的范围】\n∴ a 的取值范围为 [5,+∞) ｜ —1分 ｜ 【得分理由：写出最终范围】\n（进化点：这是本链最简单母题（构造）——正弦定理直接建立 a 与 sinB 的关系，仅由 sinB 的值域求范围。）"},"angle:R0":{"question":"已知一个确定角和另外两边之和，求第三边范围。","analysis":"由余弦定理 b²=a²+c²−2ac·cosB，把 b² 表示成 a+c 与 ac 的函数｜—1分｜【得分理由：正确建立函数关系】\n代入定和 a+c=1 消去 a+c 项｜—1分｜【得分理由：正确利用定和条件】\n由基本不等式求 ac 的范围｜—1分｜【得分理由：正确求 ac 的范围】\n由 b² 的范围开方得第三边 b 的范围｜—1分｜【得分理由：正确得出 b 的范围】"},"angle:E08":{"question":"在△ABC中，cosC+(cosA−√3sinA)cosB=0，且 a+c=1，求 b 的取值范围。","analysis":"由 C=π−A−B，得 cosC=−cos(A+B)，代入条件化简得 sinA·(sinB−√3cosB)=0｜—1分｜【得分理由：正确展开并化简条件】\n因 sinA≠0，故 sinB−√3cosB=0，即 tanB=√3，由 B∈(0,π) 得 B=π/3｜—1分｜【得分理由：正确确定角 B】\n由余弦定理 b²=a²+c²−2ac·cosB=a²+c²−ac｜—1分｜【得分理由：正确使用余弦定理】\n配方得 b²=(a+c)²−3ac，代入 a+c=1，得 b²=1−3ac｜—1分｜【得分理由：正确利用定和条件消元】\n由基本不等式 0<ac≤(a+c)²/4=1/4，得 1/4≤1−3ac<1｜—1分｜【得分理由：正确求出 ac 的范围】\n故 1/4≤b²<1，又 b>0，所以 b∈[1/2,1)｜—1分｜【得分理由：正确得出 b 的范围】"},"height:R0":{"question":"先会求三角形边 a/b/c 的范围，再换目标为高。","analysis":"设△ABC 中 BC 边上的高为 h，底边 a=BC，则 h=c·sinB=b·sinC ｜ —1分 ｜ 【得分理由：正确写出高与边、角的关系式】\n由 h=c·sinB 可知，高 h 的范围由边 c 与 sinB 共同决定 ｜ —1分 ｜ 【得分理由：明确影响高的变量】\n先求边 a/b/c 的范围，再代入对应角的正弦值，即可求出高的范围 ｜ —1分 ｜ 【得分理由：建立从边范围到高范围的转化路径】\n因此求高的范围是求边范围问题的派生目标 ｜ —1分 ｜ 【得分理由：确认目标间的派生关系】\n（进化点：目标反转——把求边范围的目标换成求高范围，高=边×sin(对应角)，是原始边范围的派生目标。）"},"height:E09":{"question":"在△ABC中，c=√3，且 b·cos((A+B)/2)=c·sinB，求 BC 边上的高的取值范围。","analysis":"(A+B)/2=(π−C)/2=π/2−C/2，故 cos((A+B)/2)=sin(C/2)，原式化为 b·sin(C/2)=c·sinB｜ —1分 ｜【得分理由：正确化简角条件】\n正弦定理 b=2RsinB、c=2RsinC 代入，得 sin(C/2)=sinC=2sin(C/2)·cos(C/2)；sin(C/2)>0，故 cos(C/2)=1/2，C=120°｜ —1分 ｜【得分理由：正确求出角 C】\nA+B=60°，又 A>0，故 B∈(0,60°)｜ —1分 ｜【得分理由：正确确定 B 的范围】\nBC 边上的高 h=c·sinB=√3·sinB｜ —1分 ｜【得分理由：正确用边角关系表示高】\nB∈(0,60°) 时 sinB∈(0,√3/2)，故 h∈(0,3/2)｜ —1分 ｜【得分理由：正确求出高的范围】"},"bisector:R0":{"question":"先会求边范围，再用角平分线长度公式。","analysis":"先由定边定角等条件求出边 b 的范围｜—1分｜【得分理由：正确求出边的范围】\n由角平分线长公式 l=2bc·cos(A/2)/(b+c) 表示角平分线长度｜—1分｜【得分理由：正确写出角平分线公式】\n把边的范围转化为角平分线的范围｜—1分｜【得分理由：正确转化目标】\n结合端点取舍写出最终范围｜—1分｜【得分理由：正确得出范围结论】\n（进化点：把目标从边换成角平分线）"},"bisector:E10":{"question":"在△ABC中，a·cosB−2a·cosC=(2c−b)cosA，b=1，AD 为 ∠A 平分线，求 AD 的取值范围。","analysis":"由正弦定理边化角，得 sinA·cosB−2sinA·cosC=(2sinC−sinB)cosA｜—1分｜【得分理由：正确边化角】\n移项得 sinAcosB+sinBcosA=2(sinAcosC+sinCcosA)，即 sin(A+B)=2sin(A+C)｜—1分｜【得分理由：正确合并角的关系】\n由 A+B=π−C，A+C=π−B，得 sinC=2sinB，由正弦定理得 c=2b=2｜—1分｜【得分理由：正确得出边的关系】\n由角平分线长公式 AD=2bc·cos(A/2)/(b+c)=4/3·cos(A/2)｜—1分｜【得分理由：正确使用角平分线长度公式】\n由 b=1，c=2 及三角形三边关系 1<a<3，得 A∈(0,π)，故 cos(A/2)∈(0,1)｜—1分｜【得分理由：正确确定角 A 的范围】\n所以 AD∈(0,4/3)｜—1分｜【得分理由：正确得出 AD 的范围】"},"bisector:E11":{"question":"在△ABC中，c=1，∠C 平分线交 AB 于 D，且 sinA+sinB=2sin∠ACB，求 CD 的取值范围。","analysis":"由正弦定理将 sinA+sinB=2sinC 边化角，得 a+b=2c=2｜—1分｜【得分理由：正确边化角】\n由角平分线长公式 CD=2ab·cos(C/2)/(a+b)=ab·cos(C/2)｜—1分｜【得分理由：正确使用角平分线长度公式】\n由余弦定理 cosC=(a²+b²−c²)/(2ab)，结合 a+b=2 得 cos²(C/2)=(1+cosC)/2=3/(4ab)｜—1分｜【得分理由：正确建立 cos(C/2) 与 ab 的关系】\n故 CD=√(3ab/4)=√3/2·√ab｜—1分｜【得分理由：正确化简目标表达式】\n由 a+b=2 及三角形三边关系 |a−b|<1，得 ab∈(3/4,1]｜—1分｜【得分理由：正确确定 ab 的范围】\n所以 CD∈(3/4,√3/2]｜—1分｜【得分理由：正确得出 CD 的范围】"},"median:R0":{"question":"先会求边范围，再用中线长公式。","analysis":"设△ABC 中 D 为 BC 中点，a=BC=2t，AD 为 BC 边上的中线 ｜ —1分 ｜ 【得分理由：正确设元】\n中线长公式：b²+c²=2(AD²+t²) ｜ —1分 ｜ 【得分理由：正确写出中线长公式】\n先由已知条件求出 b、c 的范围（或 b²+c²、bc 的范围）｜ —1分 ｜ 【得分理由：明确求解路径第一步】\n再代入中线长公式，即可得 AD 的范围 ｜ —1分 ｜ 【得分理由：建立边范围到中线范围的转化】\n（进化点：目标反转——把求边范围的目标换成求中线范围，先求边范围再套中线长公式 b²+c²=2(AD²+t²)，其中 t 为半底边。）"},"median:E14":{"question":"锐角三角形中 BC=2，sinB+sinC=2sinA，求中线 AD 的取值范围。","analysis":"设 a=BC=2，b=CA，c=AB；由正弦定理 sinB=b/2R，sinC=c/2R，sinA=a/2R ｜ —1分 ｜ 【得分理由：正确用正弦定理表示各角正弦】\n代入 sinB+sinC=2sinA 得 b+c=2a=4 ｜ —1分 ｜ 【得分理由：把正弦条件化为边的关系】\n由中线长公式 AD²=(2b²+2c²−a²)/4=(b²+c²−2)/2 ｜ —1分 ｜ 【得分理由：正确套用中线长公式】\n又 b²+c²=(b+c)²−2bc=16−2bc，故 AD²=7−bc ｜ —1分 ｜ 【得分理由：用 b+c 与 bc 表示中线平方】\n锐角条件：三边 2、b、4−b 的任意两边平方和大于第三边，即 (4−b)²<4+b² 且 b²<4+(4−b)²，得 3/2<b<5/2 ｜ —1分 ｜ 【得分理由：由锐角条件确定 b 的范围】\nbc=b(4−b) 在 (3/2,5/2) 上开口向下，最大值 4（b=2 时取到），下界趋近 15/4（端点取不到），故 bc∈(15/4,4] ｜ —1分 ｜ 【得分理由：求 bc 的范围】\n所以 3≤AD²<13/4，即 √3≤AD<√13/2 ｜ —1分 ｜ 【得分理由：由 bc 范围推出中线范围并写答】\n（进化点：加中间量——先用正弦定理把正弦条件化为边关系 b+c=4，再用中线公式与锐角条件求范围。）"},"median:E15":{"question":"锐角三角形中 (√3a)/(c·cosB)=tanB+tanC；c=2√3，D 为 AB 中点，求中线 CD 的范围。","analysis":"化切为弦：tanB+tanC=sin(B+C)/(cosB·cosC)=sinA/(cosB·cosC) ｜ —1分 ｜ 【得分理由：正确化切为弦并利用 B+C=π−A】\n代入原式得 √3a·cosC=c·sinA（cosB>0 可约去）｜ —1分 ｜ 【得分理由：化简条件得边角关系】\n由正弦定理 c·sinA=a·sinC，代入得 √3·cosC=sinC，即 tanC=√3；C∈(0,π/2)，故 C=π/3 ｜ —1分 ｜ 【得分理由：化到只含角 C 的方程并确定角】\n由余弦定理 c²=a²+b²−2ab·cosC，即 12=a²+b²−ab ｜ —1分 ｜ 【得分理由：用余弦定理建立 a、b 的关系】\n中线公式 CD²=(2a²+2b²−c²)/4=(a²+b²−6)/2=3+ab/2 ｜ —1分 ｜ 【得分理由：正确套用中线长公式】\n锐角条件：a 最大时 a²<b²+c² 且 12=a²+b²−ab，得 ab<2b² 即 a<2b；同理 b<2a，故 t=a/b∈(1/2,2) ｜ —1分 ｜ 【得分理由：把锐角条件化为 a/b 的范围】\n由 a²+b²−ab=12 得 ab=12t/(t²−t+1)，该函数在 (1/2,2) 上最大值为 12（t=1），下界趋近 8（t→1/2 或 t→2，取不到），故 ab∈(8,12] ｜ —1分 ｜ 【得分理由：求 ab 的范围】\nCD²=3+ab/2∈(7,9]，故 CD∈(√7,3] ｜ —1分 ｜ 【得分理由：推出中线范围并写答】\n（进化点：加中间量——先化简三角条件得角 C=π/3，再用余弦定理与中线公式把范围问题化为 ab 的范围。）"},"polygon:R0":{"question":"在三角形中求边长范围，作为多边形问题的母题。","analysis":"由三角形三边关系确定未知边的粗略范围｜—1分｜【得分理由：正确使用三边关系】\n用余弦定理把角度条件转化为边的关系｜—1分｜【得分理由：正确使用余弦定理】\n用锐角/钝角判定确定角的类型条件｜—1分｜【得分理由：正确判定角型】\n综合各条件求出边长范围｜—1分｜【得分理由：正确得出边的范围】"},"polygon:E12":{"question":"平面四边形 ABCD 中 ∠A=∠B=∠C=75°，BC=2，求 AB 的取值范围。","analysis":"设 θ=∠BAC，则 ∠ACB=105°−θ。在 △ABC 中由正弦定理得 AB=2sin(105°−θ)/sinθ=2[sin105°·cotθ+cos75°]｜—1分｜【得分理由：正确用正弦定理表示 AB】\n∠CAD=75°−θ，在 △ACD 中由 ∠CAD+∠ACD=45° 得 ∠ACD=θ−30°｜—1分｜【得分理由：正确求出 ∠ACD】\n由 ∠CAD>0 且 ∠ACD>0，得 30°<θ<75°｜—1分｜【得分理由：正确确定 θ 的范围】\nAB=2[sin105°·cotθ+cos75°] 在 (30°,75°) 上随 θ 增大而减小｜—1分｜【得分理由：正确判断单调性】\nθ→30° 时 AB→2(sin105°·√3+cos75°)=√2+√6；θ→75° 时 AB→4cos75°=√6−√2｜—1分｜【得分理由：正确求区间端点值】\n故 AB∈(√6−√2,√6+√2)｜—1分｜【得分理由：正确得出 AB 的范围】"},"polygon:E13":{"question":"平面五边形 ABCDE，∠A=120°，∠B=90°，∠C=120°，∠E=90°，AB=AE=3；面积 S∈[6√3,9√3] 时求 BC。","analysis":"由五边形内角和 540° 得 ∠D=540°−120°−90°−120°−90°=120°｜—1分｜【得分理由：正确求出 ∠D】\n由 AB=AE=3，∠B=∠E=90°，∠C=∠D=120°，知五边形关于 ∠A 的平分线对称，故 DE=BC｜—1分｜【得分理由：正确利用对称性】\n设 BC=DE=x，连接 AC、AD，则 △ABC≅△ADE，∠BAC=∠DAE=arctan(x/3)｜—1分｜【得分理由：正确连接辅助线并设元】\n面积 S=2×3x/2+½(9+x²)sin(120°−2arctan(x/3))=9√3/4+9x/2−√3x²/4｜—1分｜【得分理由：正确建立面积函数】\n由 CD>0 得 x<3√3，且 S 的对称轴为 x=3√3，故 S 在 (0,3√3) 上单调递增｜—1分｜【得分理由：正确确定定义域与单调性】\n令 S=6√3 得 x=√3（另一根 5√3 超出定义域舍去）；当 x→3√3 时 S→9√3｜—1分｜【得分理由：正确求区间端点】\n故 BC∈[√3,3√3)｜—1分｜【得分理由：正确得出 BC 的范围】"},"fullEdge:R0":{"question":"已知三角形两边，用三边关系求第三边范围。","analysis":"设三角形三边为 a、b、c，其中 a≥b，c 为待求的第三边｜ —1分 ｜【得分理由：正确设元】\n由三角形存在性，任意两边之和大于第三边：a+b>c（a+c>b、b+c>a 由 a≥b 自动成立）｜ —1分 ｜【得分理由：正确列出两边之和条件】\n任意两边之差小于第三边：a−b<c｜ —1分 ｜【得分理由：正确列出两边之差条件】\n合并得 a−b<c<a+b，即第三边介于两边之差与两边之和之间｜ —1分 ｜【得分理由：正确写出结论】\n（进化点：这是“边最值完整版”的根——一切边范围问题最终归结为三边关系或其加强形式。）"},"fullEdge:B1":{"question":"锐角三角形三边为 2、3、x，求 x 的范围。","analysis":"三角形存在条件（两边之和大于第三边、两边之差小于第三边）：|3−2|<x<3+2，即 1<x<5｜ —1分 ｜【得分理由：正确列出三边关系】\n分类讨论锐角条件：若 x 为最大边，则 x²<2²+3²=13，得 x<√13｜ —1分 ｜【得分理由：正确写出 x 最大时的锐角条件】\n若 3 为最大边，则 3²<2²+x²，即 9<4+x²，得 x>√5｜ —1分 ｜【得分理由：正确写出 3 最大时的锐角条件】\n综合两段范围：√5<x<√13｜ —1分 ｜【得分理由：正确合并两类范围】","similar":[{"question":"已知锐角三角形三边长分别为 3，4，x，求 x 的取值范围。","answer":"√7<x<5","analysis":"由三边关系：|4−3|<x<4+3，得 1<x<7 ｜ —1分 ｜ 【得分理由：三角形任意两边之和大于第三边、之差小于第三边】\n锐角条件：最大边平方小于另两边平方和 ｜ —1分 ｜ 【得分理由：余弦定理推论，锐角则最大边平方小于另两边平方和】\n若 x 为最大边：x²<3²+4²=25，得 x<5 ｜ —1分 ｜ 【得分理由：对 x 最大情形列锐角不等式】\n若 4 为最大边：4²<3²+x²，得 x²>7，即 x>√7 ｜ —1分 ｜ 【得分理由：对 4 最大情形列锐角不等式】\n综上：√7<x<5 ｜ —1分 ｜ 【得分理由：两情形合并得最终范围】\n（进化点：与母题同构——同为「已知两边求锐角三角形第三边范围」，仅数据由 2,3 换为 3,4，解题链（三边关系→分类锐角→合并）完全一致。）"},{"question":"已知锐角三角形三边长分别为 4，6，x，求 x 的取值范围。","answer":"2√5<x<2√13","analysis":"由三边关系：|6−4|<x<6+4，得 2<x<10 ｜ —1分 ｜ 【得分理由：三角形任意两边之和大于第三边、之差小于第三边】\n锐角条件：最大边平方小于另两边平方和 ｜ —1分 ｜ 【得分理由：余弦定理推论】\n若 x 为最大边：x²<4²+6²=52，得 x<2√13 ｜ —1分 ｜ 【得分理由：对 x 最大情形列不等式】\n若 6 为最大边：6²<4²+x²，得 x²>20，即 x>2√5 ｜ —1分 ｜ 【得分理由：对 6 最大情形列不等式】\n综上：2√5<x<2√13 ｜ —1分 ｜ 【得分理由：合并得最终范围】\n（进化点：与母题同构——数据换为 4,6,x，解题链与母题完全一致。）"},{"question":"已知锐角三角形三边长分别为 2，5，x，求 x 的取值范围。","answer":"√21<x<√29","analysis":"由三边关系：|5−2|<x<5+2，得 3<x<7 ｜ —1分 ｜ 【得分理由：三角形任意两边之和大于第三边、之差小于第三边】\n锐角条件：最大边平方小于另两边平方和 ｜ —1分 ｜ 【得分理由：余弦定理推论】\n若 x 为最大边：x²<2²+5²=29，得 x<√29 ｜ —1分 ｜ 【得分理由：对 x 最大情形列不等式】\n若 5 为最大边：5²<2²+x²，得 x²>21，即 x>√21 ｜ —1分 ｜ 【得分理由：对 5 最大情形列不等式】\n综上：√21<x<√29 ｜ —1分 ｜ 【得分理由：合并得最终范围】\n（进化点：与母题同构——数据换为 2,5,x，解题链与母题完全一致。）"},{"question":"已知锐角三角形三边长分别为 5，7，x，求 x 的取值范围。","answer":"2√6<x<√74","analysis":"由三边关系：|7−5|<x<7+5，得 2<x<12 ｜ —1分 ｜ 【得分理由：三角形任意两边之和大于第三边、之差小于第三边】\n锐角条件：最大边平方小于另两边平方和 ｜ —1分 ｜ 【得分理由：余弦定理推论】\n若 x 为最大边：x²<5²+7²=74，得 x<√74 ｜ —1分 ｜ 【得分理由：对 x 最大情形列不等式】\n若 7 为最大边：7²<5²+x²，得 x²>24，即 x>2√6 ｜ —1分 ｜ 【得分理由：对 7 最大情形列不等式】\n综上：2√6<x<√74 ｜ —1分 ｜ 【得分理由：合并得最终范围】\n（进化点：与母题同构——数据换为 5,7,x，解题链与母题完全一致。）"}]},"fullEdge:B2":{"question":"在△ABC中，cosC+(cosA−√3sinA)cosB=0，且 a+c=1，求 b 的取值范围。","analysis":"cosC=−cos(A+B)=−cosA·cosB+sinA·sinB，代入原式整理得 sinA(sinB−√3cosB)=0｜ —1分 ｜【得分理由：正确利用 C=π−A−B 化简条件】\nsinA>0，故 sinB−√3cosB=0，即 tanB=√3；又 B∈(0,π)，得 B=π/3｜ —1分 ｜【得分理由：正确求出角 B】\n余弦定理：b²=a²+c²−2ac·cosB=a²+c²−ac=(a+c)²−3ac=1−3ac｜ —1分 ｜【得分理由：正确用余弦定理表示 b²】\n由 a+c=1 及基本不等式：0<ac≤((a+c)/2)²=1/4｜ —1分 ｜【得分理由：正确确定 ac 的范围】\n∴ 1/4≤b²<1，又 b>0，得 1/2≤b<1｜ —1分 ｜【得分理由：正确求出 b 的范围】","similar":[{"question":"已知△ABC中，内角A，B，C所对边分别为a，b，c，若 (2a−c)cosB−b·cosC=0。（1）求角B的大小；（2）若b=2，求a+c的最大值。","answer":"（1）B=π/3；（2）a+c 的最大值为 4。","analysis":"（1）由 (2a−c)cosB=b·cosC，正弦定理边化角：(2sinA−sinC)cosB=sinB·cosC ｜ —1分 ｜ 【得分理由：正弦定理把边换成角】\n2sinA·cosB=sinB·cosC+sinC·cosB=sin(B+C)=sinA ｜ —1分 ｜ 【得分理由：逆用两角和正弦公式合并】\nsinA>0，故 2cosB=1，得 B=π/3 ｜ —1分 ｜ 【得分理由：解出角 B】\n（2）余弦定理：b²=a²+c²−2ac·cosB=a²+c²−ac=4 ｜ —1分 ｜ 【得分理由：代入 b=2、B=π/3】\n(a+c)²=a²+2ac+c²=4+3ac ｜ —1分 ｜ 【得分理由：把目标平方用 ac 表示】\n由 a²+c²=4+ac≥2ac，得 ac≤4 ｜ —1分 ｜ 【得分理由：基本不等式确定 ac 上界】\n故 (a+c)²≤4+12=16，a+c≤4，当 a=c=2 取等，最大值为 4 ｜ —1分 ｜ 【得分理由：代回求最大值并指明取等条件】\n（进化点：与母题同构——均由边角条件化简求 B=π/3，再用余弦定理+基本不等式求边相关最值/范围；仅目标由「已知 a+c 求 b 范围」反转为「已知 b 求 a+c 最大」，数据换为 b=2。）"},{"question":"在△ABC中，内角A，B，C的对边分别为a，b，c，且 2c−a=2b·cosA。（1）求B的大小；（2）若b=√3，①求a+c的取值范围；②求ac/(a+c)的最大值。","answer":"（1）B=π/3；（2）① a+c∈(√3,2√3]；② ac/(a+c) 的最大值为 √3/2。","analysis":"（1）cosA=(b²+c²−a²)/(2bc)，代入 2c−a=2b·cosA ｜ —1分 ｜ 【得分理由：余弦定理表示 cosA 并代入】\n整理得 b²=a²+c²−ac ｜ —1分 ｜ 【得分理由：化简条件式】\n对比 b²=a²+c²−2ac·cosB，得 cosB=1/2，即 B=π/3 ｜ —1分 ｜ 【得分理由：比较标准式求角 B】\n（2）① b²=a²+c²−ac=3，设 s=a+c，则 (a+c)²=a²+c²+2ac=3+3ac ｜ —1分 ｜ 【得分理由：余弦定理用 s 表示】\nac=(s²−3)/3 ｜ —1分 ｜ 【得分理由：解出 ac】\n由基本不等式 ac≤(a+c)²/4，得 (s²−3)/3≤s²/4，解得 s≤2√3 ｜ —1分 ｜ 【得分理由：基本不等式确定 s 上界】\n又 ac>0，得 s²>3，即 s>√3，故 a+c∈(√3,2√3] ｜ —1分 ｜ 【得分理由：确定下界并写范围】\n② ac/(a+c)=(s²−3)/(3s)，该函数在 (√3,2√3] 上递增 ｜ —1分 ｜ 【得分理由：转单变量函数】\n故最大值为 (12−3)/(3·2√3)=√3/2 ｜ —1分 ｜ 【得分理由：在端点取最大值】\n（进化点：与母题同构——均由边角条件求 B=π/3，再用余弦定理+基本不等式求边相关范围/最值；仅数据换为 b=√3，并追加 ac/(a+c) 最值一问。）"},{"question":"在△ABC中，角A，B，C所对的边分别为a，b，c，且 cosA=1/3。（1）求 sin²((B+C)/2)+cos2A 的值；（2）若a=√3，求bc的最大值。","answer":"（1）−1/9；（2）bc 的最大值为 9/4。","analysis":"（1）sin²((B+C)/2)=sin²((π−A)/2)=cos²(A/2)=(1+cosA)/2=2/3 ｜ —1分 ｜ 【得分理由：半角公式与 B+C=π−A】\ncos2A=2cos²A−1=2/9−1=−7/9 ｜ —1分 ｜ 【得分理由：二倍角余弦公式】\n原式=2/3−7/9=−1/9 ｜ —1分 ｜ 【得分理由：两部分相加】\n（2）余弦定理：a²=b²+c²−2bc·cosA，即 3=b²+c²−(2/3)bc ｜ —1分 ｜ 【得分理由：代入 a=√3、cosA=1/3】\n由 b²+c²≥2bc，得 3≥2bc−(2/3)bc=(4/3)bc ｜ —1分 ｜ 【得分理由：基本不等式建立 bc 上界】\n故 bc≤9/4，当 b=c 取等，最大值为 9/4 ｜ —1分 ｜ 【得分理由：求出最大值并指明取等条件】\n（进化点：与母题同构——同为「余弦定理+基本不等式求边积最值」；仅角由「条件化简求出」改为「直接给出 cosA=1/3」（条件显式化，省去化角求角环节），数据换为 a=√3。）"},{"question":"已知函数 f(x)=m→·n→，向量 n→=(sinx+cosx,√3cosx)，m→=(cosx−sinx,2sinx)，在锐角△ABC 中内角 A，B，C 的对边分别为 a，b，c，（1）若 f(A)=1，求角 A 的大小；（2）在（1）的条件下，a=√3，求 c+b 的最大值。","answer":"（1）A=π/3；（2）c+b 的最大值为 2√3。","analysis":"（1）f(x)=m→·n→=(cosx−sinx)(sinx+cosx)+(2sinx)(√3cosx)=cos2x+√3sin2x ｜ —1分 ｜ 【得分理由：向量点积并化简】\ncos2x+√3sin2x=2cos(2x−π/3)，故 f(A)=2cos(2A−π/3)=1，即 cos(2A−π/3)=1/2 ｜ —1分 ｜ 【得分理由：辅助角公式化】\nA∈(0,π/2)，故 2A−π/3=π/3，得 A=π/3 ｜ —1分 ｜ 【得分理由：在锐角范围解出角 A】\n（2）余弦定理：a²=b²+c²−2bc·cosA=b²+c²−bc=3 ｜ —1分 ｜ 【得分理由：代入 a=√3、A=π/3】\n(b+c)²=b²+2bc+c²=3+3bc ｜ —1分 ｜ 【得分理由：把目标平方用 bc 表示】\n由 b²+c²=3+bc≥2bc，得 bc≤3 ｜ —1分 ｜ 【得分理由：基本不等式确定 bc 上界】\n故 (b+c)²≤3+9=12，b+c≤2√3，当 b=c=√3 取等，最大值为 2√3 ｜ —1分 ｜ 【得分理由：代回求最大值并指明取等条件】\n（进化点：与母题同构——入口为向量点积（条件表现不同），核心链仍为「化角求角→余弦定理+基本不等式求边和最值」；数据换为 a=√3。）"}]},"fullEdge:B3":{"question":"在锐角△ABC中，角 A,B,C 所对的边分别为 a,b,c，且 a=2b·sinA，求 sinA+sinB+sinC 的取值范围。","analysis":"正弦定理：a=2RsinA，b=2RsinB，代入 a=2b·sinA，得 sinB=1/2｜ —1分 ｜【得分理由：正确转化边角条件】\n△ABC 为锐角三角形，故 B=π/6；又 A+C=5π/6 且 A,C∈(0,π/2)，得 A∈(π/3,π/2)｜ —1分 ｜【得分理由：正确确定 A 的范围】\nsinA+sinC=2sin((A+C)/2)·cos((A−C)/2)=2sin(5π/12)·cos((A−C)/2)｜ —1分 ｜【得分理由：正确和差化积】\n由 A∈(π/3,π/2) 得 (A−C)/2∈(−π/12,π/12)，故 sinA+sinC∈(2sin(5π/12)·cos(π/12), 2sin(5π/12)]｜ —1分 ｜【得分理由：正确确定 sinA+sinC 的范围】\n端点化简：2sin(5π/12)·cos(π/12)=sin(5π/6)+sin(π/3)=(1+√3)/2，2sin(5π/12)=(√6+√2)/2｜ —1分 ｜【得分理由：正确计算端点值】\n∴ sinA+sinB+sinC=sinA+sinC+1/2∈((3+√3)/2, (√6+√2+1)/2]｜ —1分 ｜【得分理由：正确写出值域】","similar":[{"question":"在锐角△ABC中，角A，B，C的对边分别为a，b，c，且 (sinB−sinA)/(b−c)=sinC/(a+b)。（1）求角A的大小；（2）当a=√3时，求 (b+c)/2 的取值范围。","answer":"（1）A=π/3；（2）(b+c)/2∈(3/2,√3]。","analysis":"（1）正弦定理边化角：(b−a)/(b−c)=c/(a+b) ｜ —1分 ｜ 【得分理由：正弦定理把角的正弦换成对应边】\n交叉相乘：(b−a)(a+b)=c(b−c)，即 b²−a²=bc−c² ｜ —1分 ｜ 【得分理由：整理条件式】\n得 b²+c²−a²=bc ｜ —1分 ｜ 【得分理由：移项整理】\n余弦定理：cosA=(b²+c²−a²)/(2bc)=1/2，锐角，故 A=π/3 ｜ —1分 ｜ 【得分理由：由余弦定理求角 A】\n（2）正弦定理：2R=a/sinA=√3/(√3/2)=2 ｜ —1分 ｜ 【得分理由：求外接圆直径】\n(b+c)/2=(2R/2)(sinB+sinC)=sinB+sinC ｜ —1分 ｜ 【得分理由：边化角统一角度】\nB+C=2π/3，锐角，故 B,C∈(π/6,π/2) ｜ —1分 ｜ 【得分理由：由锐角条件确定角范围】\nsinB+sinC=2sin(π/3)cos((B−C)/2)=√3cos((B−C)/2) ｜ —1分 ｜ 【得分理由：和差化积】\n(B−C)/2∈(−π/6,π/6)，故 cos((B−C)/2)∈(√3/2,1] ｜ —1分 ｜ 【得分理由：求余弦范围】\n故 (b+c)/2∈(3/2,√3] ｜ —1分 ｜ 【得分理由：代入得最终范围】\n（进化点：与母题同构——均为「边化角求角→锐角定范围→和差化积统一角度求目标范围」；仅目标由 sinA+sinB+sinC 换为 (b+c)/2，数据换为 a=√3。）"},{"question":"已知△ABC的内角A，B，C的对边分别为a，b，c，且 2sinC−sinB=tanA·cosB。（1）求A；（2）若a=2，求2c−b的取值范围。","answer":"（1）A=π/3；（2）2c−b∈(−2,4)。","analysis":"（1）tanA·cosB=sinA·cosB/cosA，两边同乘 cosA：(2sinC−sinB)cosA=sinA·cosB ｜ —1分 ｜ 【得分理由：去分母变形】\n2sinC·cosA=sinA·cosB+sinB·cosA=sin(A+B)=sinC ｜ —1分 ｜ 【得分理由：逆用两角和正弦公式】\nsinC>0，故 2cosA=1，即 A=π/3 ｜ —1分 ｜ 【得分理由：解出角 A】\n（2）正弦定理：2R=a/sinA=2/(√3/2)=4/√3 ｜ —1分 ｜ 【得分理由：求外接圆直径】\n2c−b=2R(2sinC−sinB)=(4/√3)(2sinC−sinB) ｜ —1分 ｜ 【得分理由：边化角】\nB+C=2π/3，故 2sinC−sinB=2sin(2π/3−B)−sinB=√3cosB ｜ —1分 ｜ 【得分理由：代入统一角度并化简】\n故 2c−b=(4/√3)·√3cosB=4cosB ｜ —1分 ｜ 【得分理由：化简目标表达式】\nB∈(0,2π/3)，故 cosB∈(−1/2,1)，得 2c−b∈(−2,4) ｜ —1分 ｜ 【得分理由：由角范围得目标范围】\n（进化点：与母题同构——均为「三角条件化简求角→边化角统一角度→由角范围求目标范围」；仅目标由 sin 和换为 2c−b 线性组合，数据换为 a=2。）"},{"question":"已知 a，b，c 分别为△ABC 三个内角 A，B，C 的对边，且 b·cosC+√3b·sinC−a−c=0。（1）求 tanB；（2）若 b=√6，求 (√3−1)a+2c 最大值。","answer":"（1）tanB=√3；（2）最大值为 4√3。","analysis":"（1）b·cosC+√3b·sinC=a+c，正弦定理边化角：sinB·cosC+√3sinB·sinC=sinA+sinC ｜ —1分 ｜ 【得分理由：正弦定理把边换成角】\nsinA=sin(B+C)=sinB·cosC+cosB·sinC，代入得 √3sinB·sinC=cosB·sinC+sinC ｜ —1分 ｜ 【得分理由：展开 sinA 并整理】\nsinC>0，故 √3sinB−cosB=1，即 sin(B−π/6)=1/2 ｜ —1分 ｜ 【得分理由：辅助角公式化】\nB∈(0,π)，故 B−π/6=π/6，即 B=π/3，tanB=√3 ｜ —1分 ｜ 【得分理由：解出角 B】\n（2）正弦定理：2R=b/sinB=√6/(√3/2)=2√2 ｜ —1分 ｜ 【得分理由：求外接圆直径】\n(√3−1)a+2c=2√2[(√3−1)sinA+2sinC] ｜ —1分 ｜ 【得分理由：边化角】\nA+C=2π/3，代入 sinC 化简得 (√3−1)sinA+2sinC=√3·sin(A+π/4) ｜ —1分 ｜ 【得分理由：统一角度并化简】\nsin(A+π/4)≤1，故 (√3−1)a+2c≤2√2·√3=4√3，最大值为 4√3 ｜ —1分 ｜ 【得分理由：辅助角求最大值】\n（进化点：与母题同构——「条件化简求角→边化角→统一角度求线性组合最值」；目标为带系数线性组合最大值，数据换为 b=√6。）"},{"question":"记锐角△ABC 的内角 A，B，C 的对边分别为 a，b，c，tanB=(sinA+sinC)/(cosA+cosC)。（1）求 B；（2）求 a(c−a)/b² 的取值范围。","answer":"（1）B=π/3；（2）a(c−a)/b²∈(−2/3,1/3)。","analysis":"（1）和差化积：sinA+sinC=2sin((A+C)/2)cos((A−C)/2)，cosA+cosC=2cos((A+C)/2)cos((A−C)/2) ｜ —1分 ｜ 【得分理由：分子分母和差化积】\n(A+C)/2=(π−B)/2，故 sinA+sinC=2cos(B/2)cos((A−C)/2)，cosA+cosC=2sin(B/2)cos((A−C)/2) ｜ —1分 ｜ 【得分理由：用 B 表示半角】\n约去公共因子 cos((A−C)/2)，tanB=cot(B/2)=tan(π/2−B/2) ｜ —1分 ｜ 【得分理由：约分并化为同角正切】\nB=π/2−B/2，解得 B=π/3 ｜ —1分 ｜ 【得分理由：解出角 B】\n（2）正弦定理边化角：a(c−a)/b²=sinA(sinC−sinA)/sin²B ｜ —1分 ｜ 【得分理由：边化角表示目标】\nB=π/3，sin²B=3/4，且 C=2π/3−A ｜ —1分 ｜ 【得分理由：代入 B 并消 C】\n锐角，A+C=2π/3 ⇒ A∈(π/6,π/2) ｜ —1分 ｜ 【得分理由：由锐角条件定 A 范围】\n化简得 a(c−a)/b²=(1/3)[2sin(2A+π/6)−1] ｜ —1分 ｜ 【得分理由：统一角度并化简】\n2A+π/6∈(π/2,7π/6)，故 sin(2A+π/6)∈(−1/2,1)，得原式∈(−2/3,1/3) ｜ —1分 ｜ 【得分理由：由角范围求目标范围】\n（进化点：与母题同构——「和差化积求角→锐角定范围→统一角度求比值范围」；目标为边比型 a(c−a)/b²，数据换为一般参数。）"}]},"fullEdge:B4":{"question":"在△ABC中，A=2C，且 b²=ac，求 cosB 的取值范围。","analysis":"由正弦定理，b²=ac 化为 sin²B=sinA·sinC｜ —1分 ｜【得分理由：正确将边积关系化为角关系】\nA=2C，B=π−A−C=π−3C，故 sinB=sin3C、sinA=sin2C，代入得 sin²(3C)=sin(2C)·sinC｜ —1分 ｜【得分理由：正确用 A=2C 消元】\n三倍角公式：sin3C=sinC(3−4sin²C)=sinC(4cos²C−1)，sin2C=2sinC·cosC，约去 sin²C 得 (4cos²C−1)²=2cosC｜ —1分 ｜【得分理由：正确应用三倍角公式化简】\n令 x=cosC：由 A,B,C>0 且 B=π−3C>0 得 C∈(0,π/3)，x∈(1/2,1)；方程 16x⁴−8x²−2x+1=0 在该区间内有唯一解 x≈0.745｜ —1分 ｜【得分理由：正确确定 x 的范围并判断解的唯一性】\ncosB=cos(π−3C)=−cos3C=3x−4x³≈0.581，即条件 A=2C 与 b²=ac 唯一确定三角形，cosB 为唯一确定的值｜ —1分 ｜【得分理由：正确求出 cosB】","similar":[{"question":"在锐角三角形中，a，b，c 分别是内角 A，B，C 的对应边，设 A=2C，则 2c/(c+b) 的取值范围是（　）（A．(2/3,1)　B．(1/2,1)　C．(1,+∞)　D．(1/2,+∞)）","answer":"(2/3,1)（选项 A）","analysis":"A=2C，且 A+B+C=π，得 B=π−3C ｜ —1分 ｜ 【得分理由：用倍角关系消去 B】\n锐角三角形：A=2C∈(0,π/2)、B=π−3C∈(0,π/2)，得 C∈(π/6,π/4) ｜ —1分 ｜ 【得分理由：由锐角条件确定 C 的范围】\n正弦定理边化角：2c/(c+b)=2sinC/(sinC+sinB) ｜ —1分 ｜ 【得分理由：正弦定理把边比换成正弦比】\nsinB=sin(π−3C)=sin3C=3sinC−4sin³C（三倍角公式） ｜ —1分 ｜ 【得分理由：应用三倍角公式化简 sinB】\n2sinC/(sinC+3sinC−4sin³C)=2sinC/(4sinC−4sin³C)=1/(2cos²C) ｜ —1分 ｜ 【得分理由：代入并化简目标式】\nC∈(π/6,π/4)，cos²C∈(1/2,3/4)，故 2c/(c+b)=1/(2cos²C)∈(2/3,1) ｜ —1分 ｜ 【得分理由：由角范围求目标范围】\n（进化点：与母题同构——同为「倍角关系+三倍角公式求比值范围」；母题用边积条件 b²=ac 定唯一值，本类改用锐角约束、目标换为 2c/(c+b)，解题链（边化角→三倍角→定角域→求范围）一致。）"},{"question":"在锐角△ABC中，∠A=2∠B，∠B、∠C 的对边长分别是 b，c，则 b/(b+c) 的取值范围是（　）（A．(1/4,+∞)　B．(1/4,1/2)　C．(1/4,1/3)　D．(1/3,1/2)）","answer":"(1/3,1/2)（选项 D）","analysis":"A=2B，得 C=π−3B ｜ —1分 ｜ 【得分理由：用倍角关系消去 C】\n锐角：A=2B∈(0,π/2)、C=π−3B∈(0,π/2)，得 B∈(π/6,π/4) ｜ —1分 ｜ 【得分理由：由锐角条件确定 B 的范围】\n正弦定理边化角：b/(b+c)=sinB/(sinB+sinC) ｜ —1分 ｜ 【得分理由：正弦定理把边比换成正弦比】\nsinC=sin3B=3sinB−4sin³B（三倍角公式） ｜ —1分 ｜ 【得分理由：应用三倍角公式化简 sinC】\nsinB/(sinB+3sinB−4sin³B)=1/(4cos²B) ｜ —1分 ｜ 【得分理由：代入并化简目标式】\nB∈(π/6,π/4)，cos²B∈(1/2,3/4)，故 b/(b+c)=1/(4cos²B)∈(1/3,1/2) ｜ —1分 ｜ 【得分理由：由角范围求目标范围】\n（进化点：与母题同构——同为「倍角关系+三倍角公式求比值范围」；仅倍角配对不同（A=2B）、目标换为 b/(b+c)，分母系数由 2 变 4，解题链一致。）"},{"question":"在锐角△ABC中，角 A，B，C 的对边分别为 a，b，c，若 b=2，B=2C，则 a+c 的取值范围为________。","answer":"(2√2, 2√3)","analysis":"B=2C，得 A=π−3C ｜ —1分 ｜ 【得分理由：用倍角关系消去 A】\n锐角：B=2C∈(0,π/2)、A=π−3C∈(0,π/2)，得 C∈(π/6,π/4) ｜ —1分 ｜ 【得分理由：由锐角条件确定 C 的范围】\n正弦定理：2R=b/sinB=2/sin2C，故 a=2R·sinA，c=2R·sinC ｜ —1分 ｜ 【得分理由：求外接圆直径并边化角】\na+c=(2/sin2C)(sin3C+sinC) ｜ —1分 ｜ 【得分理由：代入 A=π−3C 并合并】\nsin3C+sinC=4sinC·cos²C（三倍角公式），sin2C=2sinC·cosC，故 a+c=4cosC ｜ —1分 ｜ 【得分理由：应用三倍角公式化简】\nC∈(π/6,π/4)，cosC∈(√2/2,√3/2)，故 a+c∈(2√2,2√3) ｜ —1分 ｜ 【得分理由：由角范围求边和范围】\n（进化点：与母题同构——同为「倍角关系+三倍角公式求边和范围」；倍角配对不同（B=2C）、给定一边 b=2、目标换为边和 a+c，解题链一致。）"},{"question":"设锐角三角形 ABC 的内角 A、B、C 所对的边分别为 a、b、c，已知 a=b·cosA−a·cosB。（1）求证：B=2A；（2）求 (b+c)/a 的取值范围。","answer":"（1）已证 B=2A；（2）(b+c)/a∈(1+√2, 2+√3)。","analysis":"（1）a=b·cosA−a·cosB 移项：a(1+cosB)=b·cosA ｜ —1分 ｜ 【得分理由：移项整理条件式】\n正弦定理边化角：sinA(1+cosB)=sinB·cosA ｜ —1分 ｜ 【得分理由：正弦定理把边换成角】\nsinA+sinA·cosB=sinB·cosA，移项得 sinA=sin(B−A) ｜ —1分 ｜ 【得分理由：逆用两角差正弦公式】\nB−A=A（另一解 B=π 舍去），故 B=2A ｜ —1分 ｜ 【得分理由：解出倍角关系】\n（2）锐角：B=2A∈(0,π/2)、C=π−3A∈(0,π/2)，得 A∈(π/6,π/4) ｜ —1分 ｜ 【得分理由：由锐角条件确定 A 的范围】\n正弦定理边化角：(b+c)/a=(sinB+sinC)/sinA=(sin2A+sin3A)/sinA ｜ —1分 ｜ 【得分理由：正弦定理并代入 B=2A、C=π−3A】\nsin2A+sin3A=2sinA·cosA+3sinA−4sin³A，除以 sinA 得 4cos²A+2cosA−1 ｜ —1分 ｜ 【得分理由：应用三倍角公式化简】\nA∈(π/6,π/4)，cosA∈(√2/2,√3/2)，故 (b+c)/a=4cos²A+2cosA−1∈(1+√2,2+√3) ｜ —1分 ｜ 【得分理由：由角范围求比值范围】\n（进化点：与母题同构——同为「由边/角条件推出倍角关系→三倍角公式求比值范围」；母题直接给 A=2C，本类改为由边条件 a=bcosA−acosB 推出 B=2A，目标换为 (b+c)/a，解题链一致。）"}]},"fullEdge:B8":{"question":"在△ABC中，已知 a²+b²=2c²，求 (a+b)/c 的取值范围。","analysis":"设 t=(a+b)/c，则 a+b=tc｜ —1分 ｜【得分理由：正确设元】\n由 a²+b²=2c²：(a+b)²−2ab=2c²，得 ab=(t²−2)c²/2｜ —1分 ｜【得分理由：正确用和积关系消元】\n(a+b)²≤2(a²+b²)=4c²，得 t²≤4，即 t≤2（a=b 时取等，此时为等边三角形，可取）｜ —1分 ｜【得分理由：正确确定上界】\n(a−b)²=(a+b)²−4ab=(4−t²)c²；三角形存在要求 |a−b|<c，即 √(4−t²)<1，得 t>√3｜ —1分 ｜【得分理由：正确用三角形存在条件确定下界】\nt>√3 时 ab>0 且 a+b>c 均成立，三角形存在；∴ (a+b)/c∈(√3,2]｜ —1分 ｜【得分理由：正确写出范围】","similar":[{"question":"记△ABC 内角 A，B，C 的对边分别是 a，b，c，已知 tanB/(2tanB−tanA)=tanC/tanA（由此可证 b²+c²=2a²），求 ab/c² 的取值范围。","answer":"(3√3−5, 5+3√3)（需排除 b/c=√3 或 1/√3 时 B、C 为直角的两个例外点，不影响区间端点）","analysis":"tanB·tanA=tanC(2tanB−tanA)，交叉相乘整理 ｜ —1分 ｜ 【得分理由：化简条件式】\n用 tanA=4S/(b²+c²−a²) 等面积式代入，得 2a²=b²+c² ｜ —1分 ｜ 【得分理由：正切用面积表达并化简得齐次边关系】\n设 r=b/c，则 a/c=√((r²+1)/2)，ab/c²=r·√((r²+1)/2) ｜ —1分 ｜ 【得分理由：比值换元把目标化为 r 的函数】\n三角形存在 |b−c|<a，即 |r−1|<√((r²+1)/2)，解得 r∈(2−√3,2+√3) ｜ —1分 ｜ 【得分理由：用三边关系确定新元 r 的范围】\n目标 h(r)=r·√((r²+1)/2) 在 r∈(2−√3,2+√3) 上单调递增 ｜ —1分 ｜ 【得分理由：判断单调性求值域】\n故 ab/c²∈(h(2−√3), h(2+√3))=(3√3−5, 5+3√3) ｜ —1分 ｜ 【得分理由：代入端点求范围】\n（进化点：与母题同构——同为「齐次边关系→比值换元→三边关系定新元范围→求齐次分式范围」；母题直接给 a²+b²=2c²，本类由 tan 条件推出 b²+c²=2a²，目标换为 ab/c²，解题链一致。）"},{"question":"在锐角△ABC中，角 A，B，C 的对边分别为 a，b，c，S 为△ABC 的面积，且 2S=a²−(b−c)²，则 (2b²+c²)/(bc) 的取值范围为（　）（A．(43/15,59/15)　B．　C．　D．）","answer":"[2√2, 59/15)（选项与推导不符说明见文末交付说明；数学下界 2√2 在 b/c=1/√2 处可取到）","analysis":"2S=bc·sinA，且 a²−(b−c)²=a²−b²+2bc−c²=2bc(1−cosA) ｜ —1分 ｜ 【得分理由：面积与余弦定理代入】\nbc·sinA=2bc(1−cosA)，得 sinA=2(1−cosA) ｜ —1分 ｜ 【得分理由：化简得角关系】\ntan(A/2)=1/2，故 sinA=4/5、cosA=3/5 ｜ —1分 ｜ 【得分理由：半角关系求角 A 的正余弦】\n(2b²+c²)/(bc)=2b/c+c/b，设 t=b/c ｜ —1分 ｜ 【得分理由：比值换元化单变量】\n锐角：B,C∈(0,π/2)，B+C=π−A，得 t=sinB/sinC∈(3/5,5/3) ｜ —1分 ｜ 【得分理由：由角范围确定新元 t 的范围】\nf(t)=2t+1/t 在 (3/5,5/3) 上最小值为 2√2（t=1/√2 处），上界趋近 f(5/3)=59/15 ｜ —1分 ｜ 【得分理由：求函数最值】\n故 (2b²+c²)/(bc)∈[2√2, 59/15) ｜ —1分 ｜ 【得分理由：写出最终范围】\n（进化点：与母题同构——同为「齐次条件→比值换元→定新元范围→求齐次分式范围」；母题条件为边平方和 a²+b²=2c²，本类条件含面积 2S=a²−(b−c)²（先化出角 A），目标换为 (2b²+c²)/(bc)，解题链一致。）"},{"question":"已知△ABC 的三边长分别为 a，b，c，角 A 是钝角，则 b(c−b)/a² 的取值范围是________。","answer":"(−1, (√2−1)/2)","analysis":"设 x=b/a，y=c/a，则 x,y∈(0,1) ｜ —1分 ｜ 【得分理由：比值换元（a 最大边）】\nA 钝角 ⇒ a²>b²+c²，即 x²+y²<1；三角形存在 x+y>1 ｜ —1分 ｜ 【得分理由：把钝角与三边关系翻译到新元】\n目标 b(c−b)/a²=x(y−x) ｜ —1分 ｜ 【得分理由：目标用比值表示】\n上界：对固定 x，y<√(1−x²)，得 b(c−b)/a²<x(√(1−x²)−x) ｜ —1分 ｜ 【得分理由：求上界函数】\nf(x)=x√(1−x²)−x² 的最大值在 x²=(2−√2)/4 处，为 (√2−1)/2（A→90° 趋近取不到） ｜ —1分 ｜ 【得分理由：求最大值（开区间）】\n下界：x→1⁻、y→0⁺ 时 x(y−x)→−1（趋近取不到） ｜ —1分 ｜ 【得分理由：求下界】\n故 b(c−b)/a²∈(−1, (√2−1)/2) ｜ —1分 ｜ 【得分理由：写出最终范围】\n（进化点：与母题同构——同为「齐次分式→比值换元→用形状/三边关系定新元范围→求范围」；母题用边平方和条件，本类用钝角+三边关系约束新元，目标换为 b(c−b)/a²，解题链一致。）"},{"question":"在△ABC中，已知 a²+b²=4c²，求 (a+b)/c 的取值范围。","answer":"(√7, 2√2]","analysis":"设 t=(a+b)/c，则 a+b=tc ｜ —1分 ｜ 【得分理由：正确设元】\n由 a²+b²=4c²：(a+b)²−2ab=4c²，得 ab=(t²−4)c²/2 ｜ —1分 ｜ 【得分理由：正确用和积关系消元】\n(a−b)²=(a+b)²−4ab=c²(8−t²) ｜ —1分 ｜ 【得分理由：用平方差关系表达】\n三角形存在要求 |a−b|<c，即 √(8−t²)<1，得 t²>7，故 t>√7 ｜ —1分 ｜ 【得分理由：用三角形存在条件确定下界】\n上界：(a+b)²≤2(a²+b²)=8c²，得 t²≤8，即 t≤2√2（a=b 时取等，此时 a=b=2c/√... 等边三角形可取） ｜ —1分 ｜ 【得分理由：用不等式确定上界】\nt>√7 时 ab>0 且 a+b>c 均成立，三角形存在；∴ (a+b)/c∈(√7, 2√2] ｜ —1分 ｜ 【得分理由：正确写出范围】\n（进化点：与母题同构——**自造镜像题**，仅把齐次系数由 2 换为 4（a²+b²=4c²），目标 (a+b)/c 不变，解题链（设元→和积→三边关系定下界→不等式定上界）完全一致，答案 (√7,2√2]。）"}]},"fullEdge:B5":{"question":"在△ABC中，D 在 BC 上且 BD:DC=1:2，AD=√7，BC=3，求 AB 的取值范围。","analysis":"由 BD:DC=1:2 且 BC=3，得 BD=1，DC=2｜ —1分 ｜【得分理由：正确求出分点线段长】\n斯特瓦尔特定理：AB²·DC+AC²·BD=BC(AD²+BD·DC)，即 2AB²+AC²=3(7+2)=27｜ —1分 ｜【得分理由：正确应用斯特瓦尔特定理】\n设 AB=x，则 AC²=27−2x²；△ABC 存在要求 |AC−x|<3<AC+x｜ —1分 ｜【得分理由：正确设元并列出三角形存在条件】\n若 x≤3，则 AC≥x，由 AC−x<3 得 √(27−2x²)<x+3，平方整理得 x²+2x−6>0，故 x>√7−1｜ —1分 ｜【得分理由：正确完成第一类讨论】\n若 x>3，由 x−AC<3 得 x²−2x−6<0，故 x<√7+1｜ —1分 ｜【得分理由：正确完成第二类讨论】\n∴ √7−1<AB<√7+1｜ —1分 ｜【得分理由：正确合并范围】","similar":[{"question":"已知 D 是△ABC 的边 BC 上一点，且 BC→=3BD→，AD=2，tan∠BAC=√15，则 AC+2AB 的最大值为______。","answer":"12√10/5","analysis":"BC→=3BD→ 得 BD:DC=1:2，设 |AB|=c、|AC|=b ｜ —1分 ｜ 【得分理由：向量条件翻译为分点比，并设边】\n向量表示：D=(2/3)B→+(1/3)C→，AD²=(4c²+b²+bc·cosA)/9 ｜ —1分 ｜ 【得分理由：向量法求 AD 的平方】\ntan∠BAC=√15，得 sinA=√15/4、cosA=1/4 ｜ —1分 ｜ 【得分理由：由正切求正弦、余弦】\nAD=2 代入：4c²+b²+bc=36 ｜ —1分 ｜ 【得分理由：代入定约束方程】\n配方法：b²+bc+4c²=(b+c/2)²+(15/4)c²=36 ｜ —1分 ｜ 【得分理由：对约束式配方】\n设 u=b+c/2，则目标 AC+2AB=b+2c=u+(3/2)c，由 u²+(15/4)c²=36 用柯西不等式得 (b+2c)²≤288/5 ｜ —1分 ｜ 【得分理由：柯西不等式求目标上界】\n故 AC+2AB≤12√10/5，最大值 12√10/5 ｜ —1分 ｜ 【得分理由：求出最大值】\n（进化点：与母题同构——同为「分点比+已知 cevian 长（AD）→向量/斯特瓦尔特建立约束→求边相关量」；母题求 AB 范围（+三角形存在），本类求 AC+2AB 最大值（+柯西/配方），解题链一致，目标由范围变最值。）"},{"question":"已知 D 是△ABC 边 AC 上一点，且 CD=3AD，BD=2，cos∠ABC=1/4，则 3AB+BC 的最大值为__________。","answer":"16√10/5","analysis":"CD=3AD 得 AD=b/4、DC=3b/4（b=AC），BD=2 ｜ —1分 ｜ 【得分理由：分点比换算为线段长】\n斯特瓦尔特定理（cevian BD 到 AC）：a²·AD+c²·DC=AC(BD²+AD·DC) ｜ —1分 ｜ 【得分理由：正确套用斯特瓦尔特定理】\n代入得 4a²+12c²−3b²=64 ｜ —1分 ｜ 【得分理由：代入并整理约束式】\ncos∠ABC=1/4，余弦定理 b²=a²+c²−ac/2 ｜ —1分 ｜ 【得分理由：用已知角建立第二关系】\n消去 b²：a²+9c²+(3/2)ac=64 ｜ —1分 ｜ 【得分理由：代入消元得单一约束】\n设 r=a/c，则 3c+a=8(r+3)/√(r²+1.5r+9) ｜ —1分 ｜ 【得分理由：比值换元化单变量】\n求导最大在 r=3，最大值=8·6/√22.5=16√10/5 ｜ —1分 ｜ 【得分理由：求导数确定最大值】\n（进化点：与母题同构——同为「分点比+已知 cevian/中线长→斯特瓦尔特建立约束→求边相关量」；分点改在 AC 上（CD=3AD）、给定 BD 与 cos∠ABC，目标为 3AB+BC 最大值，解题链一致。）"},{"question":"在△ABC中，D 在 BC 上且 BD:DC=2:1，AD=√7，BC=3，求 AB 的取值范围。","answer":"√7−2<AB<√7+2","analysis":"BD:DC=2:1 且 BC=3，得 BD=2，DC=1 ｜ —1分 ｜ 【得分理由：正确求出分点线段长】\n斯特瓦尔特定理：AB²·DC+AC²·BD=BC(AD²+BD·DC)，即 AB²+2AC²=3(7+2)=27 ｜ —1分 ｜ 【得分理由：正确应用斯特瓦尔特定理】\n设 AB=x，则 AC²=(27−x²)/2 ｜ —1分 ｜ 【得分理由：正确设元并表示另一条边】\n△ABC 存在要求 |AC−x|<3，分两类讨论 ｜ —1分 ｜ 【得分理由：正确列出三角形存在条件】\n若 x≤AC（x≤3）：AC−x<3，平方整理得 x²+4x−3>0，故 x>√7−2 ｜ —1分 ｜ 【得分理由：完成第一类讨论】\n若 x>AC（x>3）：x−AC<3，平方整理得 x²−4x−3<0，故 x<√7+2 ｜ —1分 ｜ 【得分理由：完成第二类讨论】\n∴ √7−2<AB<√7+2 ｜ —1分 ｜ 【得分理由：正确合并范围】\n（进化点：与母题同构——**自造镜像题**，仅把分点比由 1:2 换为 2:1（斯特瓦尔特式由 2AB²+AC² 变 AB²+2AC²），目标同为求 AB 范围，解题链（斯特瓦尔特→设元→三角形存在分类→合并）完全一致。）"},{"question":"在△ABC中，D 在 BC 上且 BD:DC=1:2，AD=2√3，BC=3，求 AC 的取值范围。","answer":"2√3−2<AC<2√3+2","analysis":"BD:DC=1:2 且 BC=3，得 BD=1，DC=2 ｜ —1分 ｜ 【得分理由：正确求出分点线段长】\n斯特瓦尔特定理：AB²·DC+AC²·BD=BC(AD²+BD·DC)，即 2AB²+AC²=3(12+2)=42 ｜ —1分 ｜ 【得分理由：正确应用斯特瓦尔特定理】\n设 AC=x，则 AB²=(42−x²)/2 ｜ —1分 ｜ 【得分理由：正确设元并表示另一条边】\n△ABC 存在要求 |AB−x|<3，分两类讨论 ｜ —1分 ｜ 【得分理由：正确列出三角形存在条件】\n若 x≤AB（x≤√14）：AB−x<3，平方整理得 x²+4x−8>0，故 x>2√3−2 ｜ —1分 ｜ 【得分理由：完成第一类讨论】\n若 x>AB（x>√14）：x−AB<3，平方整理得 x²−4x−8<0，故 x<2√3+2 ｜ —1分 ｜ 【得分理由：完成第二类讨论】\n∴ 2√3−2<AC<2√3+2 ｜ —1分 ｜ 【得分理由：正确合并范围】\n（进化点：与母题同构——**自造镜像题**，分点比同 1:2、AD 由 √7 换为 2√3（斯特瓦尔特右端 27→42），目标由 AB 换为 AC，解题链完全一致。）"}]},"fullEdge:B6":{"question":"在△ABC中，a·cosB−2a·cosC=(2c−b)cosA，b=1，AD 为 ∠A 平分线，求 AD 的取值范围。","analysis":"原式移项得 a·cosB+b·cosA=2(a·cosC+c·cosA)｜ —1分 ｜【得分理由：正确移项整理】\n由投影定理 a·cosB+b·cosA=c、a·cosC+c·cosA=b，得 c=2b；又 b=1，故 c=2｜ —1分 ｜【得分理由：正确用投影定理化简条件】\n角平分线长公式：AD²=bc[1−a²/(b+c)²]=2(1−a²/9)｜ —1分 ｜【得分理由：正确应用角平分线长公式】\n三角形存在条件 |c−b|<a<b+c，即 1<a<3｜ —1分 ｜【得分理由：正确确定 a 的范围】\n∴ AD²=2−2a²/9∈(0,16/9)，又 AD>0，得 0<AD<4/3｜ —1分 ｜【得分理由：正确求出 AD 的范围】","similar":[{"question":"在△ABC 中，角 A，B，C 所对的边分别为 a，b，c，∠ABC=120°，∠ABC 的平分线交 AC 于点 D，且 BD=1，则 4a+c 的最小值为________。","answer":"9","analysis":"角平分线长公式：BD=2ac·cos(B/2)/(a+c)，B=120°，cos60°=1/2｜—1分｜【得分理由：角平分线长公式】\nBD=ac/(a+c)=1 ⇒ ac=a+c｜—1分｜【得分理由：代入求关系】\nc=a/(a−1)，a>1｜—1分｜【得分理由：解出 c】\n4a+c=4a+a/(a−1)｜—1分｜【得分理由：目标化单变量】\n求导：4−1/(a−1)²=0 ⇒ a=3/2｜—1分｜【得分理由：求驻点】\n最小值=4·(3/2)+3=9｜—1分｜【得分理由：求最小值】\n进化点：与母题同构——角平分线长公式建立关系+函数最值，换角 120°、目标 4a+c。"},{"question":"已知△ABC，内角 A，B，C 所对的边分别是 a，b，c，c=1，∠C 的角平分线交 AB 于点 D。若 sinA+sinB=2sin∠ACB，则 CD 的取值范围是____________。","answer":"CD∈(3/4, √3/2]","analysis":"sinA+sinB=2cos(C/2)cos((A−B)/2)，2sinC=4sin(C/2)cos(C/2)｜—1分｜【得分理由：和差化积】\ncos((A−B)/2)=2sin(C/2)≤1 ⇒ C≤π/3｜—1分｜【得分理由：定 C 范围】\nc=1 ⇒ 2R=1/sinC，a+b=2R(sinA+sinB)=2｜—1分｜【得分理由：求 a+b】\nCD 角平分线长：CD=2ab·cos(C/2)/(a+b)｜—1分｜【得分理由：角平分线长公式】\nab=3/(4cos²(C/2)) ⇒ CD=3/(4cos(C/2))｜—1分｜【得分理由：求 ab 并代回】\nC∈(0,π/3] ⇒ cos(C/2)∈[√3/2,1) ⇒ CD∈(3/4,√3/2]｜—1分｜【得分理由：求范围】\n进化点：与母题同构——条件求角关系→角平分线长→范围，换边 c=1、目标 CD。"},{"question":"在△ABC 中，角 A，B，C 所对的边分别为 a，b，c，且 (sinA+sinB)/sinC=(c+b)/(a−b)。（1）若 a=2√3，b=2，求角 B；（2）设∠BAC 的角平分线 AD 交 BC 于点 D，若△ABC 面积为 √3，求 AD 长的最大值。","answer":"（1）B=π/6；（2）AD 最大值 = 1","analysis":"(sinA+sinB)/sinC=(a+b)/c=(c+b)/(a−b)｜—1分｜【得分理由：边化角】\n(a+b)(a−b)=c(c+b) ⇒ a²=b²+c²+bc｜—1分｜【得分理由：交叉相乘化简】\ncosA=(b²+c²−a²)/(2bc)=−1/2 ⇒ A=120°｜—1分｜【得分理由：求角 A】\n（1）a=2√3，b=2：12=4+c²+2c ⇒ c=2，B=C=30° ⇒ B=π/6｜—1分｜【得分理由：解三角形求 B】\n（2）S=(1/2)bc·sinA=(√3/4)bc=√3 ⇒ bc=4｜—1分｜【得分理由：面积求 bc】\nAD 角平分线长=2bc·cos(A/2)/(b+c)=8·(1/2)/(b+c)=4/(b+c)｜—1分｜【得分理由：角平分线长公式】\nb+c≥2√(bc)=4 ⇒ AD≤1，当 b=c=2 取等｜—1分｜【得分理由：基本不等式求最值】\n进化点：与母题同构——边角条件求角→角平分线长→最值，多一问具体求角。"},{"question":"在△ABC 中，∠C=120°，∠C 的角平分线交 AB 于点 D，且 CD=1，求 a+b 的最小值。","answer":"4","analysis":"角平分线长公式：CD=2ab·cos(C/2)/(a+b)，C=120° 则 cos60°=1/2｜—1分｜【得分理由：角平分线长公式代入】\nCD=ab/(a+b)=1 ⇒ ab=a+b｜—1分｜【得分理由：代入求关系】\n两边同除 ab：1/a+1/b=1｜—1分｜【得分理由：化倒数关系】\na+b=(a+b)(1/a+1/b)=2+b/a+a/b｜—1分｜【得分理由：恒等变形】\n由基本不等式 b/a+a/b≥2，故 a+b≥4｜—1分｜【得分理由：基本不等式求下界】\n当 a=b=2 取等，故 a+b 的最小值为 4｜—1分｜【得分理由：得结论】\n进化点：与母题同构——角平分线长公式+最值，自造换角 120° 与目标 a+b 最小。"}]},"fullEdge:B9":{"question":"锐角三角形中 BC=2，sinB+sinC=2sinA，求中线 AD 的取值范围。","analysis":"由正弦定理，sinB+sinC=2sinA 化为 b+c=2a；又 BC=a=2，故 b+c=4｜ —1分 ｜【得分理由：正确化边并求出 b+c】\n中线长公式：b²+c²=2(AD²+(a/2)²)=2(AD²+1)，故 AD²=(b²+c²)/2−1｜ —1分 ｜【得分理由：正确应用中线长公式】\nb²+c²=(b+c)²−2bc=16−2bc，故 AD²=7−bc｜ —1分 ｜【得分理由：正确消元表示 AD²】\n锐角条件等价于 |b−c|<1（即任两边平方差小于第三边平方：b²<c²+a²、c²<b²+a²），由 (b−c)²<1 得 16−4bc<1，即 bc>15/4｜ —1分 ｜【得分理由：正确用锐角条件确定 bc 的下界】\n基本不等式：bc≤((b+c)/2)²=4，b=c=2 时取等（等边三角形，锐角条件成立，可取）｜ —1分 ｜【得分理由：正确确定 bc 的上界】\n∴ AD²=7−bc∈[3,13/4)，又 AD>0，得 AD∈[√3,√13/2)｜ —1分 ｜【得分理由：正确求出 AD 的范围】","similar":[{"question":"在△ABC 中，角 A，B，C 所对的边分别为 a，b，c，且 a·cosC，b·cosB，c·cosA 成等差数列，若 a+c=4，则 AC 边上中线长的最小值__________。","answer":"√3","analysis":"等差中项：2b·cosB=a·cosC+c·cosA｜—1分｜【得分理由：等差条件】\na·cosC+c·cosA=b（投影恒等式）⇒ 2cosB=1 ⇒ B=60°｜—1分｜【得分理由：求角 B】\nb²=a²+c²−ac，a+c=4｜—1分｜【得分理由：余弦定理】\nAC 边中线 m_b²=(2a²+2c²−b²)/4=(a²+c²+ac)/4=4−ac/4｜—1分｜【得分理由：中线公式】\na+c=4 ⇒ ac≤4 ⇒ m_b²≥3 ⇒ m_b≥√3，当 a=c=2 取等｜—1分｜【得分理由：求最小值】\n进化点：与母题同构——条件定角+中线长公式+基本不等式求最值，目标为 AC 边中线最小。"},{"question":"已知△ABC 的内角 A、B，C 所对的边分别为 a，b，c，若 a=4，且 4cosB=c−(1/2)b。（1）求 A；（2）若 AD 是 BC 边上的中线，求 AD 长度的最大值。","answer":"（1）A=60°；（2）AD 最大值 = 2√3","analysis":"4cosB=c−b/2，cosB=(a²+c²−b²)/(2ac)=(16+c²−b²)/(8c)｜—1分｜【得分理由：余弦定理代入】\n(16+c²−b²)/(2c)=c−b/2 ⇒ b²+c²−bc=16=a²｜—1分｜【得分理由：化简】\ncosA=(b²+c²−a²)/(2bc)=bc/(2bc)=1/2 ⇒ A=60°｜—1分｜【得分理由：求角 A】\nAD 中线²=(2b²+2c²−a²)/4，b²+c²=16+bc｜—1分｜【得分理由：中线公式】\nAD²=4+bc/2，bc≤16（b²+c²=16+bc≥2bc）⇒ AD²≤12 ⇒ AD≤2√3｜—1分｜【得分理由：求最大值】\n进化点：与母题同构——条件求角+中线长公式+基本不等式求最值，换条件与目标方向。"},{"question":"锐角三角形 ABC 中，角 A，B，C 所对的边分别为 a，b，c，且 √3·a/(c·cosB)=tanB+tanC。（1）求角 C 的值；（2）若 c=2√3，D 为 AB 的中点，求中线 CD 的范围。","answer":"（1）C=60°；（2）CD∈(√7,3]","analysis":"√3·a/(c·cosB)=tanB+tanC ⇒ √3·sinA/(sinC·cosB)=sinA/(cosB·cosC)｜—1分｜【得分理由：边化角】\n√3/sinC=1/cosC ⇒ tanC=√3 ⇒ C=60°｜—1分｜【得分理由：求角 C】\nc=2√3 ⇒ 2R=c/sinC=4｜—1分｜【得分理由：求外接圆直径】\nD 为 AB 中点，CD 中线²=(2a²+2b²−c²)/4=3+ab/2｜—1分｜【得分理由：中线公式】\nab=16sinA·sinB，A+B=120°，锐角 ⇒ A,B∈(π/6,π/2)｜—1分｜【得分理由：边化角并定角域】\nab=8(cos(A−B)+1/2)∈(8,12] ⇒ CD²∈(7,9] ⇒ CD∈(√7,3]｜—1分｜【得分理由：求范围】\n进化点：与母题同构——条件求角+中线长公式+统一角度求范围，目标为 AB 中点中线 CD。"},{"question":"在① sinA/sinB+sinB/sinA+1=c²/(ab)；② (a+2b)cosC+c·cosA=0；③ √3a·sin((A+B)/2)=c·sinA 三个条件中任选一个补充：在△ABC 中，角 A，B，C 所对的边分别为 a，b，c，且______。（1）求角 C 的大小；（2）若 c=4，求 AB 的中线 CD 长度的最小值。","answer":"（1）C=120°（①②③均得此角）；（2）CD 最小值 = 2√3/3","analysis":"选①：(a²+b²+ab)/(ab)=c²/(ab) ⇒ c²=a²+b²+ab ⇒ cosC=−1/2 ⇒ C=120°｜—1分｜【得分理由：余弦定理求角】\n（选②：(sinA+2sinB)cosC=−sinC·cosA ⇒ sinB(1+2cosC)=0 ⇒ cosC=−1/2）｜—1分｜【得分理由：选②条件复核求角】\n（选③：√3sinA·cos(C/2)=sinC·sinA ⇒ √3=2sin(C/2) ⇒ C=120°）｜—1分｜【得分理由：另两条件复核】\nc=4 ⇒ a²+b²+ab=16｜—1分｜【得分理由：余弦定理代入】\nAB 中线 CD²=(2a²+2b²−c²)/4=4−ab/2｜—1分｜【得分理由：中线公式】\na²+b²≥2ab ⇒ 16≥3ab ⇒ ab≤16/3 ⇒ CD²≥4/3 ⇒ CD≥2√3/3，当 a=b 取等｜—1分｜【得分理由：求最小值】\n进化点：与母题同构——条件求角+中线长公式+基本不等式求最值，多条件选做结构。"}]},"fullEdge:B7":{"question":"平面四边形 ABCD 中 ∠A=∠B=∠C=75°，BC=2，求 AB 的取值范围。","analysis":"四边形内角和：∠D=360°−3×75°=135°｜ —1分 ｜【得分理由：正确求出 ∠D】\n连接 AC，设 ∠BAC=α，则 ∠BCA=105°−α；由 ∠DAC=75°−α≥0 且 ∠ACD=75°−(105°−α)=α−30°≥0，得 30°≤α≤75°｜ —1分 ｜【得分理由：正确设角并确定 α 的范围】\n△ABC 中由正弦定理：AB/sin(105°−α)=BC/sinα=2/sinα，得 AB=2sin(105°−α)/sinα=2(sin75°·cotα+cos75°)｜ —1分 ｜【得分理由：正确用正弦定理表示 AB】\ncotα 在 α∈(30°,75°) 上单调递减，故 AB(α) 单调递减｜ —1分 ｜【得分理由：正确判断单调性】\n端点值：AB(75°)=√6−√2，AB(30°)=√6+√2；端点处 ∠DAC=0 或 ∠ACD=0，四边形退化，取不到｜ —1分 ｜【得分理由：正确计算端点值并处理退化】\n∴ AB∈(√6−√2, √6+√2)｜ —1分 ｜【得分理由：正确写出范围】","similar":[{"question":"在△ABC 中，BC=√2，AC=1，以 AB 为边作等腰直角三角形 ABD（B 为直角顶点，C、D 两点在直线 AB 的两侧）。当 ∠C 变化时，线段 CD 长的最大值为（ ）（A．1 B．2 C．3 D．4）","answer":"C．3","analysis":"设 AB=BD=c，则 AD=√2c（等腰直角△ABD，B 为直角顶点）｜—1分｜【得分理由：等腰直角三角形边长关系】\nC、D 在 AB 两侧 ⇒ 四点 A、C、B、D 构成四边形，托勒密不等式：AB·CD≤AC·BD+BC·AD｜—1分｜【得分理由：托勒密不等式】\nc·CD≤1·c+√2·√2·c=3c ⇒ CD≤3｜—1分｜【得分理由：代入 BC=√2、AC=1 得上界】\n当 A、C、B、D 四点共圆时取等（坐标复核：AB=√5 时 CD=3 恰可取到）｜—1分｜【得分理由：取等条件与结论】\n故最大值为 3，选 C｜—1分｜【得分理由：得答案】\n进化点：与母题同构——图形中的正余弦/托勒密工具求边最值，换为等腰直角三角形构图。"},{"question":"在平面五边形 ABCDE 中，已知 ∠A=120°，∠B=90°，∠C=120°，∠E=90°，AB=AE=3。（1）当 BC=3√3/2 时，求 CD；（2）当五边形 ABCDE 的面积 S∈[6√3,9√3] 时，求 BC 的取值范围。","answer":"（1）CD=3√3/2；（2）BC∈[√3,3√3)","analysis":"设 BC=y，由坐标闭合关系得 CD=3√3−y，DE=y｜—1分｜【得分理由：五边形角度固定的坐标关系】\n∠D=540°−120°−90°−120°−90°=120°｜—1分｜【得分理由：五边形内角和】\n面积（鞋带公式/分割）：S=9√3−(√3/4)(y−3√3)²｜—1分｜【得分理由：求面积函数】\n（1）y=3√3/2 ⇒ CD=3√3−3√3/2=3√3/2｜—1分｜【得分理由：第一问代入】\n（2）S∈[6√3,9√3] ⇒ (y−3√3)²≤12 ⇒ y∈[√3,5√3]｜—1分｜【得分理由：由面积范围解 y】\n几何要求 CD=3√3−y>0 ⇒ y<3√3｜—1分｜【得分理由：凸五边形约束】\n取交集：BC=y∈[√3,3√3)｜—1分｜【得分理由：最终范围】\n进化点：与母题同构——多边形图形分析+坐标/面积建模求边范围，三角形→五边形。"},{"question":"在三角形 ABC 中，若 sin²A+sin²B+sin²C=2√3·sinA·sinB·sinC。（1）求角 A 的大小；（2）如图所示，若 DB=2，DC=4，求 DA 长度的最大值。","answer":"（1）A=60°；（2）DA 最大值 = 6","analysis":"sin²A+sin²B+sin²C=2+2cosA·cosB·cosC（三角形恒等式）｜—1分｜【得分理由：恒等式化】\n代入：1+cosA·cosB·cosC=√3·sinA·sinB·sinC｜—1分｜【得分理由：代入条件】\n恒有 sin²A+sin²B+sin²C≥2√3·sinA·sinB·sinC，等号仅当 A=B=C=60°｜—1分｜【得分理由：不等式取等判定】\n故 A=60°｜—1分｜【得分理由：得角 A】\n（2）设 BC=x，B=(0,0)，C=(x,0)，A=(x/2,√3x/2)；D=(u,v)（v<0）｜—1分｜【得分理由：建系】\nDB=2、DC=4 ⇒ u²+v²=4，(u−x)²+v²=16 ⇒ u=(x²−12)/(2x)｜—1分｜【得分理由：距离条件】\nv²=4−u²，x∈[2,6]｜—1分｜【得分理由：定 x 范围】\nDA²=(u−x/2)²+(v−√3x/2)²=10+x²/2+√3x√(4−u²)｜—1分｜【得分理由：目标函数】\n当 x=2√7 时 u=4/√7、v=−2√3/√7，DA²=36｜—1分｜【得分理由：取等检验】\n故 DA 最大值 = 6｜—1分｜【得分理由：得结论】\n（进化点：与母题同构——三角条件+图形结构求边最值，条件为三角恒等式、构图含分点。）"},{"question":"在平面四边形 ABCD 中，△BCD 的面积是△ABD 的面积的 2/3 倍，∠DBC=2∠ABD，AB=1，BC=2。（1）求∠ABD 的大小；（2）若点 E，D 在直线 AC 同侧，∠AEC=π/3，求 AE+EC 的取值范围。","answer":"（1）∠ABD=arccos(1/6)；（2）AE+EC∈(√(187/27),2√(187/27)]","analysis":"设 ∠ABD=θ，则 ∠DBC=2θ｜—1分｜【得分理由：设角】\nS_BCD=(1/2)·BD·BC·sin2θ=BD·sin2θ；S_ABD=(1/2)·BD·AB·sinθ=(BD/2)sinθ｜—1分｜【得分理由：面积公式】\nS_BCD=(2/3)S_ABD ⇒ sin2θ=(1/3)sinθ ⇒ cosθ=1/6｜—1分｜【得分理由：代入面积比】\n故 ∠ABD=arccos(1/6)｜—1分｜【得分理由：求角】\n∠ABC=3θ ⇒ cos∠ABC=4cos³θ−3cosθ=−13/27｜—1分｜【得分理由：三倍角求 cos∠ABC】\nAC²=AB²+BC²−2·AB·BC·cos∠ABC=187/27｜—1分｜【得分理由：余弦定理求 AC】\n∠AEC=π/3 ⇒ E 在以 AC 为弦的圆弧上，AE+EC=2AC·cosδ，δ∈(−π/6,π/6)｜—1分｜【得分理由：圆弧模型化目标】\nAE+EC∈(AC,2AC]=(√(187/27),2√(187/27)]｜—1分｜【得分理由：求范围】\n进化点：与母题同构——面积/角度条件+图形（圆弧）求边和范围，构图更复杂。"}]},"fullEdge:B10":{"question":"在圆内接四边形 ABCD 中，AB=3，BC=4，CD=5，DA=6，求对角线 AC 的取值范围。","analysis":"由托勒密定理：AC·BD=AB·CD+BC·AD=3×5+4×6=39　①｜ —1分 ｜【得分理由：正确应用托勒密定理】\n设 ∠ABC=θ，由圆内接四边形对角互补得 ∠ADC=π−θ｜ —1分 ｜【得分理由：正确设角并利用对角互补】\n△ABC 中由余弦定理：AC²=3²+4²−2·3·4·cosθ=25−24cosθ；△ADC 中：AC²=5²+6²−2·5·6·cos(π−θ)=61+60cosθ｜ —1分 ｜【得分理由：正确列出两组余弦定理表达式】\n两式相等：25−24cosθ=61+60cosθ，解得 cosθ=−3/7｜ —1分 ｜【得分理由：正确解出夹角余弦】\n∴ AC²=25−24×(−3/7)=247/7，AC=√(247/7)；代回 ① 得 BD=39/AC≈6.57，满足三角形存在条件 |3−6|<BD<3+6，故给定四边的圆内接四边形唯一确定，AC=√(247/7)｜ —1分 ｜【得分理由：正确求值并完成存在性验证】","similar":[{"question":"在平面四边形 ABCD 中，CD=2，BC=2√2，△ABD 为等腰直角三角形，且 ∠ABD=90°，则 AC 长的最大值为___________。","answer":"6","analysis":"△ABD 等腰直角 ⇒ AB=BD，AD=√2·AB｜—1分｜【得分理由：边长关系】\n四边形 A-B-C-D：托勒密不等式 AC·BD≤AB·CD+BC·AD｜—1分｜【得分理由：托勒密】\nAC·AB≤AB·2+2√2·√2·AB=2AB+4AB=6AB｜—1分｜【得分理由：代入边长得关系】\nAC≤6｜—1分｜【得分理由：求上界】\nA、B、C、D 四点共圆时取等，故最大值 6｜—1分｜【得分理由：取等与结论】\n进化点：与母题同构——托勒密不等式求对角线最值，换等腰直角构图与数据。"},{"question":"四边形 ABCD 的对角线交点位于四边形的内部，AB=BC=1，AC=CD，AC⊥CD，当 ∠ABC 变化时，BD 的最大值为________。","answer":"1+√2","analysis":"AC=CD，AC⊥CD ⇒ △ACD 为等腰直角，AD=√2·AC｜—1分｜【得分理由：直角三角形关系】\n四边形 A-B-C-D：托勒密不等式 AC·BD≤AB·CD+BC·AD｜—1分｜【得分理由：托勒密】\nAC·BD≤1·AC+1·√2·AC=AC(1+√2)｜—1分｜【得分理由：代入边长得关系】\nBD≤1+√2｜—1分｜【得分理由：求上界】\n四点共圆时取等，故最大值 1+√2｜—1分｜【得分理由：得结论】\n进化点：与母题同构——托勒密不等式求对角线最值，换等腰直角△ACD 构图。"},{"question":"在平面四边形 ABCD 中，AD=1，BD=2√6/3，AB⊥AC，AC=2AB，则 CD 的最小值为_______。","answer":"(4√6−3√5)/3","analysis":"AB⊥AC，AC=2AB ⇒ 设 AB=x，AC=2x，BC=√5x｜—1分｜【得分理由：直角三角形比例】\n四边形 A-B-C-D：托勒密不等式 AC·BD≤AB·CD+BC·AD｜—1分｜【得分理由：托勒密】\n2x·(2√6/3)≤x·CD+√5x·1 ⇒ CD≥(4√6/3)−√5｜—1分｜【得分理由：代入求下界】\n四点共圆时取等（数值复核 CD_min≈1.03 可达）｜—1分｜【得分理由：验证可取到】\n故 CD 最小值 =(4√6−3√5)/3｜—1分｜【得分理由：得结论】\n进化点：与母题同构——托勒密不等式求对角线最值，换直角三角形比例构图（求最小值）。"},{"question":"在平面四边形 ABCD 中，AB=2，BC=1，△ACD 为等边三角形，设 ∠ABC=α。求四边形 ABCD 对角线 BD 长度的最大值，以及相应 α 的值。","answer":"BD 最大值 = 3，此时 α=120°","analysis":"△ACD 等边 ⇒ AC=CD=AD，各角 60°｜—1分｜【得分理由：等边三角形性质】\n四边形 A-B-C-D：托勒密不等式 AC·BD≤AB·CD+BC·AD｜—1分｜【得分理由：托勒密】\n设 AC=CD=AD=s：s·BD≤2s+1·s=3s ⇒ BD≤3｜—1分｜【得分理由：代入求上界】\n四点共圆时取等 ⇒ 圆内接四边形对角互补｜—1分｜【得分理由：取等条件】\n∠ABC+∠ADC=180°，∠ADC=60° ⇒ α=∠ABC=120°｜—1分｜【得分理由：求对应角】\n故 BD 最大值 3，相应 α=120°｜—1分｜【得分理由：得结论】\n进化点：与母题同构——托勒密不等式求对角线最值+取等求角，换等边三角形构图。"}]},"angleRange:R1":{"question":"母题：余弦定理求角。","analysis":"已知三边时，直接代入 cosA=(b²+c²−a²)/(2bc) 求角｜—1分｜【得分理由：正确代入余弦定理】\n已知两边及夹角时，先由余弦定理求出第三边｜—1分｜【得分理由：正确求出第三边】\n再由余弦定理求另一角｜—1分｜【得分理由：正确求出另一角】\n由 cosA 的值结合 A∈(0,π) 确定角 A｜—1分｜【得分理由：正确确定角】\n（进化点：这是角最值链的根）"},"angleRange:A1":{"question":"在△ABC 中，sin²A ≤ sin²B + sin²C − sinB·sinC，则 A 的取值范围是（ ）","analysis":"由正弦定理 a=2R·sinA，b=2R·sinB，c=2R·sinC，将题设两边同乘 4R²，得 a²≤b²+c²−bc｜—1分｜【得分理由：正确实现边角互化】\n由余弦定理 a²=b²+c²−2bc·cosA 代入，得 −2bc·cosA≤−bc｜—1分｜【得分理由：正确代入余弦定理】\n因 bc>0，化简得 cosA≥1/2｜—1分｜【得分理由：正确化简不等式】\n由 A∈(0,π) 及 cosA≥1/2，得 A∈(0,π/3]｜—1分｜【得分理由：正确得出 A 的范围】"},"angleRange:A2":{"question":"在△ABC 中，角 A,B,C 所对边长分别为 a,b,c，若 a² + b² = 2c²，则 cosC 的最小值为（ ）","analysis":"由余弦定理 cosC=(a²+b²−c²)/(2ab)｜—1分｜【得分理由：正确写出余弦定理】\n由 a²+b²=2c² 得 c²=(a²+b²)/2，代入得 cosC=(a²+b²)/(4ab)｜—1分｜【得分理由：正确消去 c²】\n由基本不等式 a²+b²≥2ab，得 cosC≥1/2｜—1分｜【得分理由：正确使用基本不等式求下界】\n当 a=b 时取等，此时 a=b=c 构成等边三角形，故 cosC 的最小值为 1/2｜—1分｜【得分理由：正确验证取等条件并得结论】"},"angleRange:A3":{"question":"在锐角△ABC 中，角 A,B,C 的对边分别为 a,b,c，且 2b·sinA=√3a。（Ⅰ）求角 B；（Ⅱ）求 cosA+cosB+cosC 的取值范围。","analysis":"（Ⅰ）由正弦定理 a=2R·sinA，b=2R·sinB，代入 2b·sinA=√3a，得 2sinB·sinA=√3·sinA｜—1分｜【得分理由：正确边化角】\n（Ⅰ）因 sinA≠0，得 sinB=√3/2｜—1分｜【得分理由：正确消去 sinA】\n（Ⅰ）由 △ABC 为锐角三角形，B∈(0,π/2)，故 B=π/3｜—1分｜【得分理由：正确确定角 B】\n（Ⅱ）由 A+C=2π/3，得 cosA+cosC=2cos((A+C)/2)·cos((A−C)/2)=cos((A−C)/2)｜—1分｜【得分理由：正确进行和差化积】\n（Ⅱ）由 A,C∈(0,π/2) 且 A+C=2π/3，得 (A−C)/2∈(−π/6,π/6)，故 cos((A−C)/2)∈(√3/2,1]｜—1分｜【得分理由：正确确定角的取值范围】\n（Ⅱ）所以 cosA+cosB+cosC=1/2+cos((A−C)/2)∈((1+√3)/2, 3/2]｜—1分｜【得分理由：正确得出取值范围】"},"angleRange:A4":{"question":"设△ABC 的内角 A,B,C 所对的边长分别为 a,b,c，且 a·cosB − b·cosA = (3/5)c。（Ⅰ）求 tanA/tanB 的值；（Ⅱ）求 tan(A−B) 的最大值。","analysis":"（Ⅰ）由正弦定理边化角，得 sinA·cosB−sinB·cosA=(3/5)sinC｜—1分｜【得分理由：正确边化角】\n（Ⅰ）由 C=π−A−B 得 sinC=sin(A+B)，展开整理得 2sinAcosB=8cosAsinB｜—1分｜【得分理由：正确展开并合并同类项】\n（Ⅰ）故 sinAcosB=4cosAsinB，即 tanA=4tanB，所以 tanA/tanB=4｜—1分｜【得分理由：正确得出正切比值】\n（Ⅱ）由两角差正切公式 tan(A−B)=(tanA−tanB)/(1+tanA·tanB)｜—1分｜【得分理由：正确写出差角正切公式】\n（Ⅱ）代入 tanA=4tanB，令 t=tanB>0，得 tan(A−B)=3t/(1+4t²)｜—1分｜【得分理由：正确化为关于 t 的函数】\n（Ⅱ）由基本不等式 1+4t²≥4t，得 tan(A−B)≤3/4｜—1分｜【得分理由：正确求上界】\n（Ⅱ）当 4t²=1 即 t=1/2 时取等，故 tan(A−B) 的最大值为 3/4｜—1分｜【得分理由：正确给出取等条件与结论】"},"angleRange:A5":{"question":"有一壁画，最高点 A 处离地面 12m，最低点 B 处离地面 7m。若从离地高 4m 的 C 处观赏它，若要视角 θ 最大，则离墙的距离为 _____m。","analysis":"设观者与墙的水平距离为 x m，眼睛 C 离地 4 m，则最低点 B、最高点 A 相对眼睛的高度分别为 3 m、8 m｜—1分｜【得分理由：正确建立几何模型】\n建系得 tanθ=(8/x−3/x)/(1+8×3/x²)=5x/(x²+24)｜—1分｜【得分理由：正确表示视角正切】\n由基本不等式 x²+24≥2√(24x²)，得 tanθ≤5/(4√6)｜—1分｜【得分理由：正确求正切上界】\n当 x²=24 即 x=2√6 时取等，此时视角最大，故离墙距离为 2√6 m｜—1分｜【得分理由：正确得出最值位置】"},"angleRange:A6":{"question":"在△ABC 中，BC=6，AB=2AC，点 D 在边 BC 上且 CD=2BD，则 tan∠ADC 的最大值为（ ）","analysis":"建系：取 D 为原点，BC 在 x 轴上，由 CD=2BD 且 BC=6 得 B=(−2,0)，C=(4,0)，设 A=(x,y)｜—1分｜【得分理由：正确建系并确定分点坐标】\n由 AB=2AC 得 (x+2)²+y²=4[(x−4)²+y²]，整理得 A 的轨迹为 (x−6)²+y²=16｜—1分｜【得分理由：正确求出阿氏圆方程】\ntan∠ADC=y/x，且 y²=16−(x−6)²=−x²+12x−20，故 tan²∠ADC=−1+12/x−20/x²｜—1分｜【得分理由：正确建立目标函数】\n令 u=1/x，由 x∈[2,10] 得 u∈[1/10,1/2]，f(u)=−20u²+12u−1 在 u=3/10 处取最大值｜—1分｜【得分理由：正确求二次函数最值】\n得 tan²∠ADC≤4/5，故 tan∠ADC 的最大值为 2√5/5｜—1分｜【得分理由：正确得出最值结论】"},"perimeterRange:R1":{"question":"母题：定边定角求单边最值。","analysis":"由定边定角条件，用余弦定理建立目标边与其余两边的关系｜—1分｜【得分理由：正确建立函数关系】\n用基本不等式或二次函数求单边的范围｜—1分｜【得分理由：正确求单边最值】\n把单边最值升级为三边之和（周长）的范围｜—1分｜【得分理由：正确升级目标】\n结合端点取舍写出周长的范围｜—1分｜【得分理由：正确得出周长范围】"},"perimeterRange:C1":{"question":"在△ABC中，已知 a=2，A=60°，求 b+c 的最大值。","analysis":"由正弦定理：2R=a/sinA=2/(√3/2)=4/√3 ｜ —1分 ｜ 【得分理由：求出外接圆直径】\nb+c=2R(sinB+sinC)，且 B+C=180°−A=120° ｜ —1分 ｜ 【得分理由：正弦定理表示 b+c 并求角度和】\nsinB+sinC=2sin60°·cos((B−C)/2)=√3·cos((B−C)/2)≤√3，等号当 B=C=60° ｜ —1分 ｜ 【得分理由：和差化积求上界】\nb+c≤(4/√3)·√3=4 ｜ —1分 ｜ 【得分理由：代入计算最大值】\n当 B=C=60° 时取等，故 b+c 的最大值为 4 ｜ —1分 ｜ 【得分理由：确认取等条件并写答】"},"perimeterRange:C2":{"question":"在锐角△ABC中，已知 a=2，A=60°，求周长 a+b+c 的取值范围。","analysis":"由正弦定理：2R=a/sinA=2/(√3/2)=4/√3 ｜ —1分 ｜ 【得分理由：求出外接圆直径】\nB+C=120°；由锐角条件 B<90°、C<90° 得 B∈(30°,90°) ｜ —1分 ｜ 【得分理由：由锐角条件确定 B 的范围】\nb+c=2R(sinB+sinC)=(4/√3)·2sin60°·cos(B−60°)=4cos(B−60°) ｜ —1分 ｜ 【得分理由：正弦定理与和差化积】\nB−60°∈(−30°,30°)，故 cos(B−60°)∈(√3/2,1]，b+c∈(2√3,4] ｜ —1分 ｜ 【得分理由：由角度范围求余弦范围】\n周长 a+b+c∈(2+2√3,6]：最大值 6 在 B=C=60° 时取得；最小值 2+2√3 取不到（B→30° 或 C→30° 时趋近）｜ —1分 ｜ 【得分理由：推出周长范围并说明端点取等】\n（进化点：加分类讨论——最大值与无限制情形相同，最小值需由锐角条件 B,C∈(0,90°) 确定角度范围后判断。）"},"perimeterRange:C3":{"question":"在△ABC中，已知 a+b=6，C=60°，求周长 a+b+c 的取值范围。","analysis":"由余弦定理 c²=a²+b²−2ab·cosC，代入 C=60° 得 c²=a²+b²−ab｜—1分｜【得分理由：正确使用余弦定理】\n配方得 c²=(a+b)²−3ab，代入 a+b=6 得 c²=36−3ab｜—1分｜【得分理由：正确利用定和消元】\n由基本不等式 0<ab≤(a+b)²/4=9｜—1分｜【得分理由：正确求出 ab 的范围】\n得 9≤c²<36，故 3≤c<6｜—1分｜【得分理由：正确求出 c 的范围】\n周长 L=a+b+c=6+c，所以 L∈[9,12)｜—1分｜【得分理由：正确得出周长范围】"},"perimeterRange:C4":{"question":"在四边形 ABCD 中，∠A=∠B=∠C=75°，BC=2，AB+CD=5，求四边形周长的取值范围。","analysis":"设 θ=∠BAC，AB=x，CD=y。在 △ABC 中由正弦定理及 ∠ACB=105°−θ，得 x=2[sin105°·cotθ+cos75°]｜—1分｜【得分理由：正确用正弦定理表示 AB】\n由 ∠CAD=75°−θ>0，∠ACD=θ−30°>0，得 30°<θ<75°｜—1分｜【得分理由：正确确定 θ 的范围】\n在 △ACD 中由正弦定理得 y=2√2·sin75°·(sin75°·cotθ−cos75°)｜—1分｜【得分理由：正确表示 CD】\n由 AB+CD=5 得 cotθ≈1.135，θ≈41.4°，为唯一解｜—1分｜【得分理由：正确解出 θ】\n由正弦定理 AD=2√2·sin75°·sin(θ−30°)/sinθ≈0.815｜—1分｜【得分理由：正确计算 AD】\n周长 P=AB+BC+CD+DA=2+5+AD≈7.82，由条件唯一确定｜—1分｜【得分理由：正确得出周长】"},"perimeterRange:C5":{"question":"在△ABC中，AD 为 ∠A 的平分线，AB:AC=3:4，AD=2，求三角形周长的取值范围。","analysis":"设 AB=3k，AC=4k，BC=a｜—1分｜【得分理由：正确设元表示两边】\n由角平分线定理 BD:DC=AB:AC=3:4，故 BD=3a/7，DC=4a/7｜—1分｜【得分理由：正确使用角平分线定理】\n由角平分线长公式 AD²=AB·AC−BD·DC，代入 AD=2 得 4=12k²−12a²/49｜—1分｜【得分理由：正确使用角平分线长公式】\n整理得 a²=49k²−49/3，由三角形三边关系 a>k 且 a<7k 得 k>7/12｜—1分｜【得分理由：正确建立关系并确定 k 的范围】\n周长 L=7k+a=7k+√(49k²−49/3)，L 随 k 增大而增大｜—1分｜【得分理由：正确写出周长函数】\n当 k→7/12 时 L→14/3，且 L 无上界，故 L∈(14/3,+∞)｜—1分｜【得分理由：正确得出周长范围】"},"areaRange:R1":{"question":"母题：定边定角求面积最值。","analysis":"由面积公式 S=½bc·sinA 建立面积目标｜—1分｜【得分理由：正确写出面积公式】\n由定边定角条件，用余弦定理或基本不等式求出 bc 的范围｜—1分｜【得分理由：正确求出边积范围】\n代入面积公式得 S 的上界｜—1分｜【得分理由：正确得出面积上界】\n检验取等条件并给出最值结论｜—1分｜【得分理由：正确给出最值结论】"},"areaRange:D1":{"question":"在△ABC中，已知 a=2，A=60°，求面积 S 的最大值。","analysis":"由面积公式 S=½bc·sinA=√3/4·bc｜—1分｜【得分理由：正确写出面积公式】\n由余弦定理 a²=b²+c²−2bc·cosA，代入 a=2，A=60°，得 4=b²+c²−bc｜—1分｜【得分理由：正确列出余弦定理】\n由 b²+c²≥2bc，得 4≥bc，即 bc≤4｜—1分｜【得分理由：正确求出 bc 的上界】\n故 S≤√3/4×4=√3，当 b=c=2 时取等，所以面积的最大值为 √3｜—1分｜【得分理由：正确得出面积最值】"},"areaRange:D2":{"question":"在△ABC中，已知 b+c=4，A=60°，求面积 S 的最大值。","analysis":"由面积公式 S=½bc·sinA=√3/4·bc｜—1分｜【得分理由：正确写出面积公式】\n由基本不等式 bc≤(b+c)²/4，代入 b+c=4，得 bc≤4｜—1分｜【得分理由：正确使用基本不等式】\n故 S≤√3/4×4=√3｜—1分｜【得分理由：正确得出面积上界】\n当 b=c=2 时取等，所以面积的最大值为 √3｜—1分｜【得分理由：正确给出取等条件与结论】"},"areaRange:D3":{"question":"在△ABC中，D 为 BC 中点，AD=√3，BC=2，求△ABC 面积的最大值。","analysis":"设 BD=DC=1，由中线长公式 b²+c²=2(AD²+BD²)=2(3+1)=8｜—1分｜【得分理由：正确使用中线长公式】\n由 16S²=4b²c²−(b²+c²−a²)²，代入 a=2，b²+c²=8，得 16S²=4b²c²−16｜—1分｜【得分理由：正确建立面积与边积的关系】\n由 b²+c²=8 及基本不等式得 b²c²≤16｜—1分｜【得分理由：正确求出边积上界】\n故 16S²≤64−16=48，S²≤3，当 b=c=2 时取等，面积的最大值为 √3｜—1分｜【得分理由：正确得出面积最值】"},"areaRange:D4":{"question":"在△ABC中，三边为 a,b,c，且 a+b+c=6，求面积 S 的最大值。","analysis":"半周长 p=(a+b+c)/2=3｜—1分｜【得分理由：正确计算半周长】\n由海伦公式 S=√[p(p−a)(p−b)(p−c)]=√[3(3−a)(3−b)(3−c)]｜—1分｜【得分理由：正确写出海伦公式】\n因 (3−a)+(3−b)+(3−c)=9−6=3 为定值，由均值不等式，三因子相等时乘积最大｜—1分｜【得分理由：正确使用均值不等式】\n当 3−a=3−b=3−c=1，即 a=b=c=2 时，Smax=√(3×1×1×1)=√3｜—1分｜【得分理由：正确得出面积最值】"},"areaRange:D5":{"question":"在△ABC中，a²+b²+c²=12，求面积 S 的最大值。","analysis":"由外森比克不等式 a²+b²+c²≥4√3·S｜—1分｜【得分理由：正确使用外森比克不等式】\n代入 a²+b²+c²=12，得 S≤12/(4√3)=√3｜—1分｜【得分理由：正确代入并求上界】\n当 a=b=c=2 时取等，此时 a²+b²+c²=12 成立｜—1分｜【得分理由：正确验证取等条件】\n故面积的最大值为 √3｜—1分｜【得分理由：正确得出最值结论】"},"areaRange:D6":{"question":"在△ABC中，BC=4，AB=2AC，求△ABC 面积的最大值。","analysis":"建系：取 B=(0,0)，C=(4,0)，设 A=(x,y)｜—1分｜【得分理由：正确建系】\n由 AB=2AC 得 x²+y²=4[(x−4)²+y²]，整理得 A 的轨迹为 (x−16/3)²+y²=64/9｜—1分｜【得分理由：正确求出阿氏圆方程】\n面积 S=½·BC·|y|=2|y|｜—1分｜【得分理由：正确表示面积】\n|y| 的最大值为半径 8/3，故 Smax=2×8/3=16/3｜—1分｜【得分理由：正确得出面积最值】"},"areaRange:D7":{"question":"在四边形 ABCD 中，AB=3，BC=4，CD=3，DA=4，∠A=∠C=90°，求四边形面积的最大值。","analysis":"连接 BD，将四边形分成 △ABD 与 △BCD｜—1分｜【得分理由：正确分割四边形】\n在 △ABD 中，∠A=90°，AB=3，AD=4，由勾股定理得 BD=5，面积 S₁=½×3×4=6｜—1分｜【得分理由：正确计算△ABD 的面积】\n在 △BCD 中，∠C=90°，BC=4，CD=3，由勾股定理得 BD=5，面积 S₂=½×4×3=6｜—1分｜【得分理由：正确计算△BCD 的面积】\n两块面积确定且相加，S=S₁+S₂=12，故四边形面积的最大值为 12｜—1分｜【得分理由：正确得出面积最值】"},"monotone:R0":{"question":"求函数 f(x)=x³−3x 的单调区间。","analysis":"求导：f′(x)=3x²−3=3(x−1)(x+1) ｜ —1分 ｜ 【得分理由：求导并因式分解正确】\n令 f′(x)>0：x<−1 或 x>1 ｜ —1分 ｜ 【得分理由：解导数大于零的不等式】\n令 f′(x)<0：−1<x<1 ｜ —1分 ｜ 【得分理由：解导数小于零的不等式】\n∴ 增区间 (−∞,−1)、(1,+∞)，减区间 (−1,1) ｜ —1分 ｜ 【得分理由：正确写出单调区间】\n（进化点：这是“求单调区间”的课本母题——求导→因式分解→定号→写区间，无参数、无超越函数。）"},"monotone:M01":{"question":"函数 f(x)=xlnx−3x+2 的单调递减区间为______。","analysis":"定义域：x>0，即 (0,+∞) ｜ —1分 ｜ 【得分理由：正确写出对数函数定义域】\n求导：f′(x)=lnx+1−3=lnx−2 ｜ —1分 ｜ 【得分理由：乘积法则求导正确】\n令 f′(x)<0，即 lnx−2<0，得 lnx<2 ｜ —1分 ｜ 【得分理由：由单调递减转化为导数小于零】\n解得 0<x<e² ｜ —1分 ｜ 【得分理由：解对数不等式得区间】\n∴ 递减区间为 (0,e²) ｜ —1分 ｜ 【得分理由：正确写出单调递减区间】\n（进化点：单知识点→组合——叠加对数函数（乘积法则求导），且必须先注意定义域。）"},"monotone:M02":{"question":"已知函数 f(x)=8x−sinx/cos³x，x∈(0,π/2)，讨论 f(x) 的单调性。","analysis":"求导：f′(x)=8−(cos²x+3sin²x)/cos⁴x ｜ —1分 ｜ 【得分理由：商与幂的求导法则正确】\n换元 t=cos²x（则 sin²x=1−t），得 f′(x)=(8t²+2t−3)/t² ｜ —1分 ｜ 【得分理由：换元并通分整理正确】\n解 8t²+2t−3=0：Δ=4+96=100，t=1/2 或 t=−3/4（舍去，因 t=cos²x>0）｜ —1分 ｜ 【得分理由：正确求零点并舍去负根】\ncos²x=1/2 且 x∈(0,π/2)，得 x=π/4 ｜ —1分 ｜ 【得分理由：由 t 反解出 x】\nx∈(0,π/4) 时 t>1/2，f′(x)>0，f 单调递增；x∈(π/4,π/2) 时 t<1/2，f′(x)<0，f 单调递减 ｜ —1分 ｜ 【得分理由：分区间判断导数符号】\n（进化点：单知识点→组合——叠加三角函数，且需换元 t=cos²x 后再解二次不等式定号。）"},"monotone:M03":{"question":"设函数 f(x)=a²x²+3ax−2lnx+1，其中 a>0，讨论 f(x) 的单调性。","analysis":"定义域：(0,+∞) ｜ —1分 ｜ 【得分理由：对数函数要求 x>0】\n求导：f′(x)=2a²x+3a−2/x=(2a²x²+3ax−2)/x ｜ —1分 ｜ 【得分理由：幂函数与对数分别求导并通分正确】\n因式分解：(2a²x²+3ax−2)/x=(2ax−1)(ax+2)/x ｜ —1分 ｜ 【得分理由：十字相乘分解正确】\na>0、x>0 ⇒ ax+2>0 恒成立，故 f′(x) 的符号只由 2ax−1 决定 ｜ —1分 ｜ 【得分理由：判断因子恒正、简化定号】\n令 2ax−1=0 得 x=1/(2a)；0<x<1/(2a) 时 f′(x)<0，x>1/(2a) 时 f′(x)>0 ｜ —1分 ｜ 【得分理由：分区间判断导数符号】\n∴ 减区间 (0,1/(2a))，增区间 (1/(2a),+∞) ｜ —1分 ｜ 【得分理由：正确写出单调区间】\n（进化点：具体→参数——系数参数化，但因 a>0 限定仍可唯一定号；零点 1/(2a) 随 a 移动，引入“参数零点”概念。）"},"monotone:M05":{"question":"设函数 f(x)=⅓x³−(a+2)/2·x²+2ax，其中 a∈R，讨论 f(x) 的单调性。","analysis":"求导：f′(x)=x²−(a+2)x+2a ｜ —1分 ｜ 【得分理由：多项式逐项求导正确】\n因式分解：x²−(a+2)x+2a=(x−2)(x−a) ｜ —1分 ｜ 【得分理由：十字相乘分解正确】\n分类一 a<2：x<a 或 x>2 时 f′(x)>0，f 单调递增；a<x<2 时 f′(x)<0，f 单调递减 ｜ —1分 ｜ 【得分理由：比较两零点大小后定号】\n分类二 a=2：f′(x)=(x−2)²≥0，f 在 R 上单调递增 ｜ —1分 ｜ 【得分理由：两零点重合，导数非负】\n分类三 a>2：x<2 或 x>a 时 f′(x)>0，f 单调递增；2<x<a 时 f′(x)<0，f 单调递减 ｜ —1分 ｜ 【得分理由：比较两零点大小后定号】\n综上：a<2 时增 (−∞,a)、(2,+∞)，减 (a,2)；a=2 时在 R 上单调递增；a>2 时增 (−∞,2)、(a,+∞)，减 (2,a) ｜ —1分 ｜ 【得分理由：分类完整、结论正确】\n（进化点：加分类讨论——参数零点 a 与常数零点 2 的大小关系不定，是分类的临界点。）"},"monotone:M06":{"question":"已知函数 f(x)=2lnx−(2a+1)x+½ax² (a∈R)，讨论函数 f(x) 的单调性。","analysis":"定义域：(0,+∞) ｜ —1分 ｜ 【得分理由：对数函数要求 x>0】\n求导：f′(x)=2/x−(2a+1)+ax=(ax−1)(x−2)/x ｜ —1分 ｜ 【得分理由：求导、通分、因式分解正确】\n分类一 a≤0：ax−1<0 恒成立，故 0<x<2 时 f′(x)>0 单调递增，x>2 时 f′(x)<0 单调递减 ｜ —1分 ｜ 【得分理由：判断因子符号并定号】\n分类二 a=1/2：f′(x)=(1/2)(x−2)²/x≥0，f 在 (0,+∞) 上单调递增 ｜ —1分 ｜ 【得分理由：完全平方式非负】\n分类三 0<a<1/2：1/a>2，故增区间 (0,2)、(1/a,+∞)，减区间 (2,1/a) ｜ —1分 ｜ 【得分理由：比较 1/a 与 2 的大小后定号】\n分类四 a>1/2：1/a<2，故增区间 (0,1/a)、(2,+∞)，减区间 (1/a,2) ｜ —1分 ｜ 【得分理由：比较 1/a 与 2 的大小后定号】\n（进化点：加分类讨论（升级）——参数零点 1/a 既要与常数零点 2 比较，还要与定义域边界 0 交叉。）"},"monotone:M10":{"question":"已知函数 f(x)=x³−3ax+a²。(1) 讨论 f(x) 的单调性；(2) 当 a>−1 时，证明 f(a)>−3。","analysis":"（1）求导：f′(x)=3x²−3a=3(x²−a) ｜ —1分 ｜ 【得分理由：求导正确】\n（1）分类一 a≤0：x²−a≥0 恒成立，f′(x)≥0，f 在 R 上单调递增 ｜ —1分 ｜ 【得分理由：判断导数非负】\n（1）分类二 a>0：令 f′(x)=0 得 x=±√a；x<−√a 或 x>√a 时 f′(x)>0，−√a<x<√a 时 f′(x)<0，故增区间 (−∞,−√a)、(√a,+∞)，减区间 (−√a,√a) ｜ —1分 ｜ 【得分理由：分区间定号并写单调区间】\n（2）f(a)=a³−3a·a+a²=a³−2a²，设 g(a)=a³−2a² ｜ —1分 ｜ 【得分理由：代入并构造函数】\n（2）g′(a)=3a²−4a=a(3a−4)，零点 a=0、a=4/3 ｜ —1分 ｜ 【得分理由：求导并求零点】\n（2）a∈(−1,0) 时 g′>0，g 单调递增；a∈(0,4/3) 时 g′<0，g 单调递减；a∈(4/3,+∞) 时 g′>0，g 单调递增 ｜ —1分 ｜ 【得分理由：分区间判断 g 的单调性】\n（2）g(4/3)=64/27−32/9=−32/27>−3；a∈(−1,0) 时 g 递增，g(a)>g(−1)=−1−2=−3 ｜ —1分 ｜ 【得分理由：极值与端点值均大于 −3】\n（2）∴ 对一切 a>−1，g(a)>−3，即 f(a)>−3 ｜ —1分 ｜ 【得分理由：综合得出结论】\n（进化点：单知识点→组合——讨论单调性之后再叠加不等式证明。）"},"monotoneExp:R0":{"question":"求函数 f(x)=e^x−x 的单调区间。","analysis":"求导：f′(x)=e^x−1 ｜ —1分 ｜ 【得分理由：求导正确】\n令 f′(x)=0 得 x=0，零点显式可解 ｜ —1分 ｜ 【得分理由：求驻点】\nx<0 时 f′(x)<0，f 单调递减；x>0 时 f′(x)>0，f 单调递增 ｜ —1分 ｜ 【得分理由：分区间定号】\n∴ 减区间 (−∞,0)，增区间 (0,+∞) ｜ —1分 ｜ 【得分理由：正确写出单调区间】\n（进化点：母题要点——指数函数求导后零点显式、符号一目了然。）"},"monotoneExp:E01":{"question":"已知函数 f(x)=e^x−ax−a³，求函数 f(x) 的单调区间。","analysis":"求导：f′(x)=e^x−a ｜ —1分 ｜ 【得分理由：指数函数与幂函数分别求导正确】\n分类一 a≤0：e^x>0 且 −a≥0，f′(x)>0 恒成立，f 在 R 上单调递增 ｜ —1分 ｜ 【得分理由：判断导数恒正】\n分类二 a>0：令 f′(x)=0 得 x=lna ｜ —1分 ｜ 【得分理由：解指数方程得零点】\nx<lna 时 f′(x)<0，f 单调递减；x>lna 时 f′(x)>0，f 单调递增 ｜ —1分 ｜ 【得分理由：分区间定号并写单调区间】\n（进化点：具体→参数——零点从 0 变为 lna，新增“零点有无”分类（a≤0 无零点 / a>0 有零点）。）"},"monotoneExp:E02":{"question":"已知函数 f(x)=e^x−x−lnx，定义域为 x∈(0,+∞)，求 f(x) 的单调区间。","analysis":"定义域 (0,+∞)，求导：f′(x)=e^x−1−1/x ｜ —1分 ｜ 【得分理由：求导正确】\nf″(x)=e^x+1/x²>0，故 f′ 在 (0,+∞) 上严格单调递增 ｜ —1分 ｜ 【得分理由：证明 f′ 的单调性】\nf′(1/2)=√e−3<0，f′(1)=e−2>0 ｜ —1分 ｜ 【得分理由：两端点定号】\n由零点存在定理，存在唯一 x₀∈(1/2,1) 使 f′(x₀)=0 ｜ —1分 ｜ 【得分理由：证明隐零点存在且唯一】\n0<x<x₀ 时 f′(x)<0，f 单调递减；x>x₀ 时 f′(x)>0，f 单调递增 ｜ —1分 ｜ 【得分理由：以隐零点为界定号】\n∴ 减区间 (0,x₀)，增区间 (x₀,+∞) ｜ —1分 ｜ 【得分理由：正确写出单调区间】\n（进化点：加中间量——导数零点 x₀ 无法显式解出（隐零点），必须先证存在且唯一，再以此为界分区间。）"},"monotoneExp:E03":{"question":"求函数 f(x)=e^x−½x² 的单调区间。","analysis":"求导：f′(x)=e^x−x，无法直接分解定号 ｜ —1分 ｜ 【得分理由：求导并判断需进一步研究】\n二阶求导：f″(x)=e^x−1，令 f″(x)=0 得 x=0 ｜ —1分 ｜ 【得分理由：二阶求导并求零点】\nx<0 时 f″<0，f′ 单调递减；x>0 时 f″>0，f′ 单调递增 ｜ —1分 ｜ 【得分理由：判断 f′ 的单调性】\nf′(x)≥f′(0)=1>0 恒成立 ｜ —1分 ｜ 【得分理由：求 f′ 的最小值定号】\n∴ f(x) 在 R 上单调递增 ｜ —1分 ｜ 【得分理由：由导数恒正得结论】\n（进化点：单知识点→组合——导数无法直接定号时，用二阶导数研究一阶导数的单调性与最值。）"},"monotoneParam:R0":{"question":"若函数 f(x)=x³+ax 在 R 上单调递增，求实数 a 的取值范围。","analysis":"求导：f′(x)=3x²+a ｜ —1分 ｜ 【得分理由：求导正确】\nf 在 R 上单调递增 ⇒ f′(x)≥0 对一切 x∈R 恒成立 ｜ —1分 ｜ 【得分理由：单调性与导数符号的转化】\n3x²+a≥0 恒成立，即 a≥−3x² 恒成立 ｜ —1分 ｜ 【得分理由：分离参数正确】\n3x²≥0，故 −3x²≤0，其最大值为 0（x=0 处取得），∴ a≥0 ｜ —1分 ｜ 【得分理由：求右侧函数的最大值】\n（进化点：母题要点——单调性→导数恒正→恒成立求参数，最基础的“单调性反求参数”题。）"},"monotoneParam:P01":{"question":"若函数 f(x)=x²−alnx+1 在 [1,+∞) 上单调递增，则实数 a 的取值范围为______。","analysis":"求导：f′(x)=2x−a/x ｜ —1分 ｜ 【得分理由：幂函数与对数分别求导正确】\nf 在 [1,+∞) 上单调递增 ⇒ f′(x)≥0 对一切 x≥1 恒成立 ｜ —1分 ｜ 【得分理由：单调性与导数符号的转化】\n2x−a/x≥0，即 a≤2x² 对 x≥1 恒成立 ｜ —1分 ｜ 【得分理由：分离参数正确】\nx≥1 时 2x² 单调递增，最小值为 2（x=1 处取得）｜ —1分 ｜ 【得分理由：求右侧函数的最小值】\n∴ a≤2，即 a∈(−∞,2] ｜ —1分 ｜ 【得分理由：写出参数范围】\n（进化点：单知识点→组合——叠加对数后导数变分式，分离参数后需求 g(x)=2x² 在区间上的最小值。）"},"monotoneParam:P02":{"question":"已知函数 f(x)=alnx−x+1。对任意的 x1,x2∈(0,1]，当 x1<x2 时，都有 ¼[f(x1)−f(x2)]<(x2−x1)/(x1x2)，求实数 a 的取值范围。","analysis":"变形右边：(x2−x1)/(x1x2)=1/x1−1/x2，条件化为 ¼[f(x1)−f(x2)]<1/x1−1/x2 ｜ —1分 ｜ 【得分理由：右边拆为倒数差】\n移项：f(x1)−4/x1<f(x2)−4/x2 ｜ —1分 ｜ 【得分理由：同乘 4 并移项整理】\n构造 g(x)=f(x)−4/x=alnx−x−4/x+1，则 g 在 (0,1] 上单调递增 ｜ —1分 ｜ 【得分理由：构造函数并转化为单调性】\ng′(x)=a/x−1+4/x²≥0 在 (0,1] 上恒成立，分离参数得 a≥x−4/x 恒成立 ｜ —1分 ｜ 【得分理由：单调递增转化为导数非负】\ny=x−4/x 在 (0,1] 上单调递增（x 增大、−4/x 增大），最大值为 y(1)=1−4=−3 ｜ —1分 ｜ 【得分理由：求右侧函数的最大值】\n∴ a≥−3 ｜ —1分 ｜ 【得分理由：写出参数范围】\n（进化点：加中间量——先把条件不等式改造成函数 g(x)=f(x)−4/x，转成单调性，再转恒成立求参。）"},"quadFormV:R0":{"question":"已知二次函数图象的顶点为O(0,0)，且经过点A(1,1)，求该二次函数的解析式。","analysis":"顶点在原点，设二次函数解析式为 y=ax² ｜ —1分 ｜ 【得分理由：由顶点位置设解析式】\n代入点 A(1,1)，得 1=a·1²，即 a=1 ｜ —1分 ｜ 【得分理由：待定系数法列方程】\na=1≠0，符合二次函数定义 ｜ —1分 ｜ 【得分理由：检验系数】\n因此二次函数的解析式为 y=x² ｜ —1分 ｜ 【得分理由：写出解析式】"},"quadFormV:V1":{"question":"已知二次函数图象与x轴的一个交点坐标为(4,0)，顶点坐标为(1,1)，求该二次函数的解析式。","analysis":"由顶点 (1,1)，设 y=a(x−1)²+1 ｜ —1分 ｜ 【得分理由：由顶点坐标设顶点式】\n代入 x 轴交点 (4,0)，得 0=a·3²+1=9a+1 ｜ —1分 ｜ 【得分理由：代入已知点列方程】\n解得 a=−1/9 ｜ —1分 ｜ 【得分理由：解方程求 a】\n因此解析式为 y=−1/9(x−1)²+1 ｜ —1分 ｜ 【得分理由：写出解析式】"},"quadFormG:G0":{"question":"已知二次函数y=ax²+4的图象经过点(2,8)，求该二次函数的解析式。","analysis":"因图象经过点 (2,8)，将该点坐标代入解析式 y=ax²+4 ｜ —1分 ｜ 【得分理由：确定代入方法】\n得 8=a·2²+4=4a+4 ｜ —1分 ｜ 【得分理由：正确代入并列方程】\n移项得 4a=4，解得 a=1 ｜ —1分 ｜ 【得分理由：解一元一次方程】\na=1≠0，符合二次函数定义，故解析式为 y=x²+4 ｜ —1分 ｜ 【得分理由：检验系数并写出解析式】"},"quadFormG:G1":{"question":"已知二次函数y=1/2x²+bx+c的图象经过点(2,0)和(8,6)，求该二次函数的解析式。","analysis":"把点 (2,0) 代入 y=½x²+bx+c，得 2+2b+c=0 ｜ —1分 ｜ 【得分理由：代入第一点列方程】\n把点 (8,6) 代入，得 32+8b+c=6 ｜ —1分 ｜ 【得分理由：代入第二点列方程】\n两式相减得 30+6b=6，解得 b=−4 ｜ —1分 ｜ 【得分理由：消元求 b】\n代回 2+2b+c=0，得 c=6 ｜ —1分 ｜ 【得分理由：求 c】\n因此解析式为 y=½x²−4x+6 ｜ —1分 ｜ 【得分理由：写出解析式】"},"quadFormG:G2":{"question":"二次函数图象经过点A(-4,0)、B(0,4)、C(4,4)，求该二次函数的解析式。","analysis":"设解析式为 y=ax²+bx+c ｜ —1分 ｜ 【得分理由：正确设一般式】\n代入三点得 16a−4b+c=0、c=4、16a+4b+c=4 ｜ —1分 ｜ 【得分理由：代入三点列方程组】\n由 c=4 化简得 16a−4b=−4、16a+4b=0 ｜ —1分 ｜ 【得分理由：利用 c=4 化简方程组】\n两式相加得 32a=−4，解得 a=−1/8；代回得 b=1/2 ｜ —1分 ｜ 【得分理由：解方程组求 a、b】\n因此解析式为 y=−1/8x²+1/2x+4 ｜ —1分 ｜ 【得分理由：写出解析式】"},"quadFormX:X0":{"question":"已知二次函数y=a(x+1)(x-3)的图象经过点(0,3)，求该二次函数的解析式。","analysis":"把点 (0,3) 代入 y=a(x+1)(x−3)，得 3=a·1·(−3) ｜ —1分 ｜ 【得分理由：正确代入坐标】\n即 3=−3a，解得 a=−1 ｜ —1分 ｜ 【得分理由：解方程求 a】\na=−1≠0，符合二次函数定义 ｜ —1分 ｜ 【得分理由：检验系数】\n因此解析式为 y=−(x+1)(x−3) ｜ —1分 ｜ 【得分理由：写出解析式】"},"quadFormX:X1":{"question":"已知二次函数图象与x轴交于点(-1,0)和(3,0)，且经过点(0,3)，求该二次函数的解析式。","analysis":"由图象与 x 轴交于 (−1,0)、(3,0)，设 y=a(x+1)(x−3) ｜ —1分 ｜ 【得分理由：由横轴交点设交点式】\n代入点 (0,3)，得 3=a·1·(−3)=−3a ｜ —1分 ｜ 【得分理由：代入已知点列方程】\n解得 a=−1 ｜ —1分 ｜ 【得分理由：解方程求 a】\n因此解析式为 y=−(x+1)(x−3) ｜ —1分 ｜ 【得分理由：写出解析式】"},"quadFormS:S1":{"question":"二次函数y=ax²+bx+c的图象经过点A(3,0)、B(2,-3)，并且以直线x=1为对称轴，求该二次函数的解析式。","analysis":"由对称轴 x=−b/(2a)=1，得 b=−2a ｜ —1分 ｜ 【得分理由：用对称轴公式建立 a、b 关系】\n代入 A(3,0) 得 9a+3b+c=0，代入 B(2,−3) 得 4a+2b+c=−3 ｜ —1分 ｜ 【得分理由：代入两点列方程】\n两式相减得 5a+b=3，与 b=−2a 联立 ｜ —1分 ｜ 【得分理由：消元建立方程组】\n解得 a=1、b=−2，代回得 c=−3 ｜ —1分 ｜ 【得分理由：解方程组求系数】\n因此解析式为 y=x²−2x−3 ｜ —1分 ｜ 【得分理由：写出解析式】"},"quadFormT:T0":{"question":"将抛物线y=2x²向右平移1个单位，再向下平移3个单位，求所得抛物线的解析式。","analysis":"原抛物线 y=2x² 的顶点为 (0,0) ｜ —1分 ｜ 【得分理由：确定原顶点】\n向右平移 1 个单位、向下平移 3 个单位后，顶点变为 (1,−3) ｜ —1分 ｜ 【得分理由：按平移方向计算新顶点】\n平移不改变开口方向与形状，二次项系数仍为 2 ｜ —1分 ｜ 【得分理由：确认二次项系数不变】\n由新顶点 (1,−3) 与系数 2 写出顶点式 y=2(x−1)²−3 ｜ —1分 ｜ 【得分理由：写出平移后解析式】"},"quadFormT:T1":{"question":"将抛物线y=2(x-2)²+4向右平移1个单位，再向下平移3个单位，求所得抛物线的解析式。","analysis":"原抛物线 y=2(x−2)²+4 的顶点为 (2,4) ｜ —1分 ｜ 【得分理由：确定原顶点】\n向右平移 1 个单位、向下平移 3 个单位后，顶点变为 (3,1) ｜ —1分 ｜ 【得分理由：按平移方向计算新顶点】\n平移不改变开口方向与形状，二次项系数仍为 2 ｜ —1分 ｜ 【得分理由：确认二次项系数不变】\n由新顶点 (3,1) 与系数 2 写出顶点式 y=2(x−3)²+1 ｜ —1分 ｜ 【得分理由：写出平移后解析式】"},"quadShiftV:V0":{"question":"将抛物线y=2x²向右平移2个单位，再向下平移3个单位，求平移后抛物线的解析式。","analysis":"原抛物线 y=2x² 的顶点为 O(0,0)，二次项系数为 2 ｜ —1分 ｜ 【得分理由：提取原抛物线信息】\n向右平移 2 个单位、向下平移 3 个单位后，顶点变为 (2,−3) ｜ —1分 ｜ 【得分理由：按平移方向计算新顶点】\n平移不改变图象形状，二次项系数仍为 2 ｜ —1分 ｜ 【得分理由：确认二次项系数不变】\n由新顶点 (2,−3) 与系数 2 写出顶点式 y=2(x−2)²−3 ｜ —1分 ｜ 【得分理由：写出平移后解析式】","questionImage":"images/quadshift_v0_q.png","answerImage":"images/quadshift_v0_a.png"},"quadShiftV:V1":{"question":"将抛物线y=2x²向右平移2个单位，再向下平移3个单位，再向左平移1个单位，求平移后抛物线的解析式。","analysis":"原抛物线 y=2x² 的顶点为 O(0,0)，二次项系数为 2 ｜ —1分 ｜ 【得分理由：提取原抛物线信息】\n右 2、下 3、再左 1 累计后，顶点变为 (0+2−1, 0−3)=(1,−3) ｜ —1分 ｜ 【得分理由：累计平移计算新顶点】\n平移不改变图象形状，二次项系数仍为 2 ｜ —1分 ｜ 【得分理由：确认二次项系数不变】\n由新顶点 (1,−3) 与系数 2 写出顶点式 y=2(x−1)²−3 ｜ —1分 ｜ 【得分理由：写出平移后解析式】"},"quadShiftV:V2":{"question":"将抛物线y=2x²向右平移2个单位，再向下平移3个单位，再向左平移1个单位，再向上平移2个单位，求平移后抛物线的解析式。","analysis":"原抛物线 y=2x² 的顶点为 O(0,0)，二次项系数为 2 ｜ —1分 ｜ 【得分理由：提取原抛物线信息】\n右 2、下 3、左 1、上 2 累计后，顶点变为 (0+2−1, 0−3+2)=(1,−1) ｜ —1分 ｜ 【得分理由：累计平移计算新顶点】\n平移不改变图象形状，二次项系数仍为 2 ｜ —1分 ｜ 【得分理由：确认二次项系数不变】\n由新顶点 (1,−1) 与系数 2 写出顶点式 y=2(x−1)²−1 ｜ —1分 ｜ 【得分理由：写出平移后解析式】"},"quadShiftA:A0":{"question":"将抛物线y=x²-4x+1向右平移2个单位，再向上平移3个单位，求平移后抛物线的解析式。","analysis":"配方：y=x²−4x+1=(x−2)²−3，原顶点为 (2,−3) ｜ —1分 ｜ 【得分理由：配方正确并确定原顶点】\n向右平移 2 个单位、向上平移 3 个单位后，顶点变为 (4,0) ｜ —1分 ｜ 【得分理由：按平移方向计算新顶点】\n平移不改变开口与形状，二次项系数仍为 1 ｜ —1分 ｜ 【得分理由：确认二次项系数不变】\n由新顶点 (4,0) 写出顶点式 y=(x−4)² ｜ —1分 ｜ 【得分理由：写出平移后解析式】"},"quadShiftA:A1":{"question":"将抛物线y=x²-4x+1向右平移2个单位，再向上平移3个单位，再向左平移1个单位，求平移后抛物线的解析式。","analysis":"配方：y=x²−4x+1=(x−2)²−3，原顶点为 (2,−3) ｜ —1分 ｜ 【得分理由：配方正确并确定原顶点】\n右 2、上 3、再左 1 累计后，顶点变为 (2+2−1, −3+3)=(3,0) ｜ —1分 ｜ 【得分理由：累计平移计算新顶点】\n平移不改变开口与形状，二次项系数仍为 1 ｜ —1分 ｜ 【得分理由：确认二次项系数不变】\n由新顶点 (3,0) 写出顶点式 y=(x−3)² ｜ —1分 ｜ 【得分理由：写出平移后解析式】"},"quadShiftA:A2":{"question":"将抛物线y=x²-4x+1向右平移2个单位，再向上平移3个单位，再向左平移1个单位，再向下平移2个单位，求平移后抛物线的解析式。","analysis":"配方：y=x²−4x+1=(x−2)²−3，原顶点为 (2,−3) ｜ —1分 ｜ 【得分理由：配方正确并确定原顶点】\n右 2、上 3、左 1、下 2 累计后，顶点变为 (2+2−1, −3+3−2)=(3,−2) ｜ —1分 ｜ 【得分理由：累计平移计算新顶点】\n平移不改变开口与形状，二次项系数仍为 1 ｜ —1分 ｜ 【得分理由：确认二次项系数不变】\n由新顶点 (3,−2) 写出顶点式 y=(x−3)²−2 ｜ —1分 ｜ 【得分理由：写出平移后解析式】"},"quadShiftG:G0":{"question":"抛物线C₁的顶点为A(-1,2)，二次项系数为a=2。将C₁向右平移4个单位，再向下平移3个单位得到C₂，求所得抛物线的解析式。","analysis":"由题意，原抛物线 C₁ 的顶点为 A(−1,2)，二次项系数为 2 ｜ —1分 ｜ 【得分理由：提取原抛物线信息】\n向右平移 4 个单位、向下平移 3 个单位后，顶点变为 B(3,−1) ｜ —1分 ｜ 【得分理由：按平移方向计算新顶点】\n平移保持图象形状不变，二次项系数仍为 2 ｜ —1分 ｜ 【得分理由：确认二次项系数不变】\n由新顶点 (3,−1) 与系数 2 写出顶点式 y=2(x−3)²−1 ｜ —1分 ｜ 【得分理由：写出平移后解析式】"},"quadShiftG:G1":{"question":"抛物线C₁的顶点为A(-1,2)，二次项系数为a=2。将C₁向右平移4个单位，再向下平移3个单位，再向左平移1个单位得到C₂，求所得抛物线的解析式。","analysis":"由题意，原抛物线 C₁ 的顶点为 A(−1,2)，二次项系数为 2 ｜ —1分 ｜ 【得分理由：提取原抛物线信息】\n右 4、下 3、再左 1 累计后，顶点变为 (−1+4−1, 2−3)=(2,−1) ｜ —1分 ｜ 【得分理由：累计平移计算新顶点】\n平移保持图象形状不变，二次项系数仍为 2 ｜ —1分 ｜ 【得分理由：确认二次项系数不变】\n由新顶点 (2,−1) 与系数 2 写出顶点式 y=2(x−2)²−1 ｜ —1分 ｜ 【得分理由：写出平移后解析式】"},"quadShiftG:G2":{"question":"抛物线C₁的顶点为A(-1,2)，二次项系数为a=2。将C₁向右平移4个单位，再向下平移3个单位，再向左平移1个单位，再向上平移2个单位得到C₂，求所得抛物线的解析式。","analysis":"由题意，原抛物线 C₁ 的顶点为 A(−1,2)，二次项系数为 2 ｜ —1分 ｜ 【得分理由：提取原抛物线信息】\n右 4、下 3、左 1、上 2 累计后，顶点变为 (−1+4−1, 2−3+2)=(2,1) ｜ —1分 ｜ 【得分理由：累计平移计算新顶点】\n平移保持图象形状不变，二次项系数仍为 2 ｜ —1分 ｜ 【得分理由：确认二次项系数不变】\n由新顶点 (2,1) 与系数 2 写出顶点式 y=2(x−2)²+1 ｜ —1分 ｜ 【得分理由：写出平移后解析式】"},"quadAppProfit:R0":{"question":"某商品每天的利润 W（元）与销售单价 x（元）满足 W = -x² + 80x - 1200，其中 20 ≤ x ≤ 60。求该商品可获得的最大利润及此时销售单价。","analysis":"利润函数 W=−x²+80x−1200 是二次函数，a=−1<0，开口向下，有最大值 ｜ —1分 ｜ 【得分理由：判断开口方向确定最值性质】\n配方：W=−(x²−80x)−1200=−(x−40)²+400 ｜ —1分 ｜ 【得分理由：配方正确】\n对称轴 x=40，恰在定义域 20≤x≤60 内部 ｜ —1分 ｜ 【得分理由：确认顶点在定义域内】\n顶点即最大值点：最大利润 Wmax=400 元，此时销售单价 x=40 元 ｜ —1分 ｜ 【得分理由：正确写出最大利润与单价】\n答：最大利润为 400 元，此时销售单价为 40 元 ｜ —1分 ｜ 【得分理由：完整作答】\n（进化点：这是本链最简单母题（构造）——直接给出利润函数，只需配方求最值，不需要自建函数或求解附加量。）"},"quadAppProfit:B1":{"question":"某商场经营一种小商品，已知购进时单价是 20 元。调查发现：当销售单价是 30 元时，月销售量为 280 件；而销售单价每上涨 1 元，月销售量就减少 10 件。当月销售利润最大时，销售单价为________元。","analysis":"设销售单价为 x 元（x≥30），则每件利润为 x−20 元｜—1分｜【得分理由：正确设元并表示利润】\n销量=280−10(x−30)=580−10x｜—1分｜【得分理由：正确表示销量】\n月利润 P=(x−20)(580−10x)=−10x²+780x−11600｜—1分｜【得分理由：正确建立利润函数】\n对称轴 x=−780/(2×(−10))=39，开口向下，x=39 时 P 最大｜—1分｜【得分理由：正确求最值点】\n答：当月销售利润最大时，销售单价为 39 元｜—1分｜【得分理由：正确作答】"},"quadAppProfit:B2":{"question":"端午节……市场上豆沙粽的进价比猪肉粽的进价每盒便宜 10 元，某商家用 8000 元购进的猪肉粽和用 6000 元购进的豆沙粽盒数相同。在销售中，该商家发现猪肉粽每盒售价 50 元时，每天可售出 100 盒；每盒售价提高 1 元时，每天少售出 2 盒。①求猪肉粽和豆沙粽每盒的进价；②设猪肉粽每盒售价 x 元（50≤x≤65），y 表示该商家每天销售猪肉粽的利润（单位：元），求 y 关于 x 的函数解析式并求最大利润。","analysis":"①设猪肉粽每盒进价为 a 元，则豆沙粽每盒进价为 a−10 元｜—1分｜【得分理由：正确设元】\n①由盒数相同得 8000/a=6000/(a−10)，解得 a=40｜—1分｜【得分理由：正确列出并解方程】\n①故猪肉粽进价 40 元，豆沙粽进价 30 元｜—1分｜【得分理由：正确得出进价】\n②售价 x 元时每盒利润为 x−40 元，销量=100−2(x−50)=200−2x｜—1分｜【得分理由：正确表示销量】\n②利润 y=(x−40)(200−2x)=−2x²+280x−8000（50≤x≤65）｜—1分｜【得分理由：正确建立利润函数】\n②对称轴 x=70 不在 [50,65] 内，开口向下，y 在 [50,65] 上递增｜—1分｜【得分理由：正确判断区间单调性】\n②故 x=65 时 ymax=(65−40)×70=1750 元｜—1分｜【得分理由：正确得出最大利润】"},"quadAppProfit:B3":{"question":"某书店销售儿童书刊，一天可销售出 20 套，每套利润 40 元。为了扩大销量，增加盈利，尽快减少库存，书店决定采取降价销售，若一套书每降价 1 元，平均每天可多售出 2 套。设每套书降价 x 元时，书店一天可获利 y 元。①求 y 关于 x 的函数表达式，并写出自变量的取值范围；②若要书店每天盈利 1200 元，则需降价多少元？③当每套书盈利多少元时，书店可获得最大利润？最大利润为多少？","analysis":"①降价 x 元后每套利润为 40−x 元，每天销量为 20+2x 套｜—1分｜【得分理由：正确表示利润与销量】\n①y=(40−x)(20+2x)=−2x²+60x+800（0≤x<40）｜—1分｜【得分理由：正确建立利润函数】\n②令 y=1200，得 x²−30x+200=0，解得 x=10 或 x=20｜—1分｜【得分理由：正确解方程】\n②故需降价 10 元或 20 元｜—1分｜【得分理由：正确作答】\n③对称轴 x=15 在区间 [0,40) 内，开口向下，x=15 时 y 最大｜—1分｜【得分理由：正确求最值点】\n③此时每套盈利 40−15=25 元，最大利润 y(15)=25×50=1250 元｜—1分｜【得分理由：正确得出最大利润】"},"quadAppTrajectory:R0":{"question":"如图，小明抛投一个沙包，沙包被抛出后距离地面的高度 h（米）和飞行时间 t（秒）近似满足函数关系式 h=−1/10(t−6)²+5，则沙包在飞行过程中距离地面的最大高度是________米，此时飞行时间为________秒。","analysis":"h=−1/10(t−6)²+5 为顶点式，顶点横坐标 t=6、纵坐标 h=5 ｜ —1分 ｜ 【得分理由：正确识别顶点式结构】\n二次项系数 −1/10<0，开口向下，函数在顶点处取得最大值 ｜ —1分 ｜ 【得分理由：判断开口方向确定最值性质】\n顶点即飞行最高点：最大高度为 5 米 ｜ —1分 ｜ 【得分理由：读出最大高度】\n取得最大高度时，飞行时间为 t=6 秒 ｜ —1分 ｜ 【得分理由：读出对应飞行时间】\n（进化点：这是抛物线型轨迹的基础形态——解析式直接给出，读顶点即得答案。）","questionImage":"images/traj_沙包.png"},"quadAppTrajectory:B1":{"question":"为了在校运会中取得更好的成绩，小丁积极训练，在某次试投中铅球所经过的路线是如图所示的抛物线的一部分。已知铅球出手处 A 距离地面的高度是 1.68 米，当铅球运行的水平距离为 2 米时，达到最大高度 2 米的 B 处，则小丁此次投掷的成绩是________米。","analysis":"设抛物线解析式为 y=a(x−2)²+2（顶点为 B(2,2)）｜ —1分 ｜ 【得分理由：由最高点设顶点式】\n图象过出手点 A(0,1.68)，代入得 4a+2=1.68，解得 a=−0.08 ｜ —1分 ｜ 【得分理由：待定系数法求 a 正确】\n落地时 y=0：−0.08(x−2)²+2=0 ｜ —1分 ｜ 【得分理由：正确列出落地方程】\n解得 (x−2)²=25，x=−3 或 x=7，取 x=7（向前飞行方向）｜ —1分 ｜ 【得分理由：解方程并取舍负根】\n∴ 小丁此次投掷的成绩为 7 米 ｜ —1分 ｜ 【得分理由：写出最终答案】\n（进化点：解析式不再直接给出，需先设顶点式、待定系数求 a。）","questionImage":"images/traj_铅球.png"},"quadAppTrajectory:B2":{"question":"如图，一座桥孔为抛物线形的拱桥，当水面宽 AB 为 12 m 时，桥孔顶部离水面 4 m。若水面上涨 1 m，求此时水面的宽。","analysis":"建系：以水面 AB 为 x 轴、拱顶所在竖直线为 y 轴，则 A(0,0)、B(12,0)，拱顶为 (6,4) ｜ —1分 ｜ 【得分理由：正确建立坐标系并定位关键点】\n设抛物线为 y=a(x−6)²+4，代入 A(0,0) 得 36a+4=0，解得 a=−1/9 ｜ —1分 ｜ 【得分理由：待定系数求解析式】\n水面上涨 1 m 后，水面所在高度 y=1：1=−1/9(x−6)²+4 ｜ —1分 ｜ 【得分理由：正确代入上涨后的水面高度】\n解得 (x−6)²=27，由对称性水面宽为 2√27=6√3≈10.4 m ｜ —1分 ｜ 【得分理由：由对称性求水面宽】\n（进化点：先建系求解析式（中间量），再代值求水面宽。）","questionImage":"images/traj_拱桥.png"},"quadAppTrajectory:B3":{"question":"一次足球训练中，小明从球门正前方将球射向球门，球射向球门的路线呈抛物线。当球飞行的水平距离为 6 m 时，球达到最高点，此时球离地面 3 m。已知球门高是 2.44 m，若足球能射入球门，则小明与球门的距离可能是（ ）。A. 10 m；B. 8 m；C. 6 m；D. 5 m。","analysis":"设抛物线 y=a(x−6)²+3（最高点为 (6,3)）；球从地面踢出，图象过 (0,0)，得 36a+3=0，a=−1/12 ｜ —1分 ｜ 【得分理由：设顶点式并待定系数】\n能射入球门需球的高度 y≤2.44 ｜ —1分 ｜ 【得分理由：把进球条件转化为高度不等式】\n−1/12(x−6)²+3≤2.44，得 (x−6)²≥6.72，即 x≥8.59（取正向）｜ —1分 ｜ 【得分理由：解不等式求水平距离下界】\n球落地时 y=0，解得 x=12，故球在 x<12 内飞行 ｜ —1分 ｜ 【得分理由：确定水平距离上界】\n所以 8.59≤x<12，四个选项中只有 10 m 符合 ｜ —1分 ｜ 【得分理由：对照选项选出答案】\n（进化点：需按球门高度区间分类判断，综合程度最高。）"},"quadAppArea:R0":{"question":"用总长 20 m 的篱笆围成一个矩形苗圃（四边都围），设一边长为 x m，面积为 S m²。①求 S 与 x 的函数关系式；②当 x 为多少时 S 最大，最大面积是多少？","analysis":"①另一边长=(20−2x)/2=10−x｜—1分｜【得分理由：正确表示另一边长】\n①面积 S=x(10−x)=−x²+10x（0<x<10）｜—1分｜【得分理由：正确建立面积函数】\n②配方 S=−(x−5)²+25，对称轴 x=5 在区间 (0,10) 内｜—1分｜【得分理由：正确配方并定位对称轴】\n②开口向下，故 x=5 时 Smax=25 m²｜—1分｜【得分理由：正确得出最值】\n（进化点：这是面积最值的基础形态：单约束建函数、配方求最值）"},"quadAppArea:B1":{"question":"在美化校园的活动中，某兴趣小组用总长为 28 米的围栏材料，一面靠墙，围成一个矩形花园，墙长 8 米，设 AB 的长为 x 米，矩形花园的面积为 S 平方米，当 x 为多少时，S 取得最大值，最大值是多少？","analysis":"围栏围三边（靠墙的 AD 边不用）：AB+BC+CD=28，AB=CD=x，得 BC=28−2x｜—1分｜【得分理由：正确表示平行于墙的边】\n墙长 8 m 限制平行于墙的边 BC=AD≤8，即 28−2x≤8，得 x≥10；由 BC>0 得 x<14，定义域 10≤x<14｜—1分｜【得分理由：正确确定定义域】\n面积 S=x·BC=x(28−2x)=−2x²+28x｜—1分｜【得分理由：正确建立面积函数】\n对称轴 x=7 不在区间 [10,14) 内，开口向下，故 S 在 [10,14) 上递减｜—1分｜【得分理由：正确判断区间单调性】\n所以 x=10 时 Smax=10×8=80 m²｜—1分｜【得分理由：正确得出最值并作答】\n（进化点：新增墙长限制截断定义域，对称轴落在区间外→最值取在区间端点，需先判对称轴位置；注意图中 AB 为垂直于墙的短边，故 x=10 而非 8）","questionImage":"images/area_花园.png"},"quadAppArea:B2":{"question":"投资 1 万元围成一个矩形菜园（如图），其中一边靠墙，另外三边选用不同材料建造，墙长 24 m，平行于墙的边的费用为 200 元/米，垂直于墙的边的费用为 150 元/米，设平行于墙的边长为 x m。①设垂直于墙的一边长为 y m，直接写出 y 与 x 之间的函数关系式；②若菜园的面积为 384 m²，求 x 的值；③求菜园的最大面积。","analysis":"①由费用约束 200x+2×150y=10000，得 y=(100−2x)/3（0<x≤24）｜—1分｜【得分理由：正确列出费用方程】\n②面积 S=x·y=x(100−2x)/3=384，整理得 x²−50x+576=0｜—1分｜【得分理由：正确建立面积方程】\n②解得 x=18 或 x=32，由 0<x≤24 舍去 32，得 x=18｜—1分｜【得分理由：正确取舍方程的解】\n③S=−2x²/3+100x/3，对称轴 x=25 不在 (0,24] 内，开口向下，S 在 (0,24] 上递增｜—1分｜【得分理由：正确判断区间单调性】\n③故 x=24 时 Smax=24×52/3=416 m²｜—1分｜【得分理由：正确得出最大面积】\n（进化点：新增费用约束（中间量 y），并需反求与区间取点）","questionImage":"images/area_菜园.png"},"quadAppArea:B3":{"question":"如图是一个迷宫游戏盘的局部平面简化示意图，该矩形的长、宽分别为 5 cm、3 cm，其中阴影部分为迷宫中的挡板，设挡板的宽度为 x cm，小球滚动的区域（空白区域）面积为 y cm²，则下列所列方程正确的是（ ）。A. y=5×3−3x−5x；B. y=(5−x)(3−x)；C. y=3x+5x；D. y=(5−x)(3−x)+5x²","analysis":"矩形总面积为 5×3=15｜—1分｜【得分理由：正确计算总面积】\n横向挡板面积为 3x，纵向挡板面积为 5x，重叠部分 x² 被重复扣除｜—1分｜【得分理由：正确识别各部分面积】\n空白面积=15−3x−5x+x²=(5−x)(3−x)｜—1分｜【得分理由：正确建立空白面积表达式】\n对照选项知选 B｜—1分｜【得分理由：正确选择答案】\n（进化点：从图形关系中代数化（几何→代数），需识别重叠部分）","questionImage":"images/area_迷宫.png"},"quadAppGraph:R0":{"question":"某商店购进一批成本为每件 30 元的商品。经测算，该商品每天的销售量 y（件）与销售单价 x（元）的关系为 y=−2x+160（30≤x≤60）。求销售单价定为多少元时，每天销售该商品获得的利润 W 最大？最大利润是多少？","analysis":"每件利润为 x−30 元，销量 y=−2x+160｜—1分｜【得分理由：正确表示每件利润】\n利润 W=(x−30)(−2x+160)=−2x²+220x−4800（30≤x≤60）｜—1分｜【得分理由：正确建立利润函数】\n对称轴 x=55 在区间 [30,60] 内，开口向下｜—1分｜【得分理由：正确定位对称轴】\n故 x=55 时 Wmax=(55−30)×50=1250 元｜—1分｜【得分理由：正确得出最值】\n（进化点：这是图象题的基础形态：销量函数直接给出，建利润函数配方求最值）"},"quadAppGraph:B1":{"question":"安顺市某商贸公司以每千克 40 元的价格购进一种干果，计划以每千克 60 元的价格销售。为了让顾客得到更大的实惠，现决定降价销售，已知这种干果销售量 y（千克）与每千克降价 x（元）（0<x<20）之间满足一次函数关系，其图象如图所示（直线过点 (2,120)、(4,140)）。①求 y 与 x 之间的函数关系式；②若商贸公司要想获得最大利润，则这种干果每千克应降价多少元？","analysis":"①设 y=kx+b，图象过 (2,120)、(4,140)，得 k=10，b=100，故 y=10x+100（0<x<20）｜—1分｜【得分理由：正确求出一次函数】\n②每千克利润为 20−x 元，利润 W=(20−x)(10x+100)=−10x²+100x+2000｜—1分｜【得分理由：正确建立利润函数】\n②对称轴 x=5 在区间 (0,20) 内，开口向下｜—1分｜【得分理由：正确定位对称轴】\n②故 x=5 时 Wmax=(20−5)×150=2250 元｜—1分｜【得分理由：正确得出最值】\n答：每千克降价 5 元，最大利润为 2250 元｜—1分｜【得分理由：正确作答】\n（进化点：基础形态：读图两点建函数+利润最值）","questionImage":"images/graph_干果.png"},"quadAppGraph:B2":{"question":"某超市以 20 元/千克进货价购进一批绿色食品。若以 30 元/千克销售这些绿色食品，则每天可售出 400 千克。由销售经验可知，每天的销售量 y（千克）与销售单价 x（元）（x≥30）存在如图所示的一次函数关系（直线过点 (30,400)、(40,200)）。①求 y 与 x 的一次函数表达式；②当 x 为多少时，这批绿色食品每天的利润达到最大？并求出此时的最大利润。","analysis":"①设 y=kx+b，图象过 (30,400)、(40,200)，得 k=−20，b=1000，故 y=−20x+1000（x≥30）｜—1分｜【得分理由：正确求出一次函数】\n②每千克利润为 x−20 元，利润 W=(x−20)(−20x+1000)=−20x²+1400x−20000｜—1分｜【得分理由：正确建立利润函数】\n②对称轴 x=35 在定义域 x≥30 内，开口向下｜—1分｜【得分理由：正确定位对称轴】\n②故 x=35 时 Wmax=(35−20)×300=4500 元｜—1分｜【得分理由：正确得出最值】\n答：售价定为 35 元/千克，最大利润为 4500 元｜—1分｜【得分理由：正确作答】\n（进化点：进价/售价关系由题目直接给出，销量图象一点已知一点读图）","questionImage":"images/graph_食品.png"},"quadAppGraph:B3":{"question":"某商店购进一批成本为每件 30 元的商品。经调查发现，该商品每天的销售量 y（件）与销售单价 x（元）之间满足一次函数关系，其图象如图所示（直线过点 (30,100)、(45,70)）。①求该商品每天的销售量 y 与销售单价 x 之间的函数关系式；②若商店按单价不低于成本价，且不高于 50 元销售，则销售单价定为多少，才能使销售该商品每天获得的利润 W（元）最大？最大利润是多少？","analysis":"①设 y=kx+b，图象过 (30,100)、(45,70)，得 k=−2，b=160，故 y=−2x+160｜—1分｜【得分理由：正确求出一次函数】\n②每件利润为 x−30 元，利润 W=(x−30)(−2x+160)=−2x²+220x−4800｜—1分｜【得分理由：正确建立利润函数】\n②对称轴 x=55 不在区间 [30,50] 内，开口向下，故 W 在 [30,50] 上递增｜—1分｜【得分理由：正确判断区间单调性】\n②故 x=50 时 Wmax=(50−30)×60=1200 元｜—1分｜【得分理由：正确得出最值】\n答：销售单价定为 50 元，最大利润为 1200 元｜—1分｜【得分理由：正确作答】\n（进化点：最值受区间限制，需判断对称轴与区间位置（分类讨论））","questionImage":"images/graph_商品.png"},"quadAppProfit:B4":{"question":"果县是全国优质黄花主产地，某加工厂加工黄花的成本为 30 元/千克。根据市场调查发现，批发价定为 48 元/千克时，每天可销售 500 千克。为增大市场占有率，在保证盈利的情况下，工厂采取降价措施，批发价每千克降低 1 元，每天销量可增加 50 千克。①写出工厂每天的利润 W 与降价 x 元之间的函数关系；当降价 2 元时，工厂每天的利润为多少元？②当降价多少元时，工厂每天的利润最大，最大为多少元？③若工厂每天的利润要达到 9750 元，并让利于民，则定价应为多少元？","analysis":"①降价 x 元后，每千克利润为 48−30−x=18−x 元，每天销量为 500+50x 千克 ｜ —1分 ｜ 【得分理由：正确表示单件利润与销量】\n①W=(18−x)(500+50x)=−50x²+400x+9000 ｜ —1分 ｜ 【得分理由：正确建立利润函数模型】\n①当 x=2 时，W=(18−2)(500+100)=16×600=9600 元 ｜ —1分 ｜ 【得分理由：代入计算正确】\n②对称轴 x=−400/(2×(−50))=4，开口向下，故 x=4 时 W 最大 ｜ —1分 ｜ 【得分理由：正确确定最值点】\n②Wmax=(18−4)(500+200)=14×700=9800 元 ｜ —1分 ｜ 【得分理由：计算最大利润正确】\n③令 W=9750：−50x²+400x+9000=9750，整理得 x²−8x+15=0，解得 x=3 或 x=5 ｜ —1分 ｜ 【得分理由：正确列方程并求解】\n③让利于民应选降价较多者，取 x=5 ｜ —1分 ｜ 【得分理由：按题意取舍降价幅度】\n③定价为 48−5=43 元 ｜ —1分 ｜ 【得分理由：正确计算定价并作答】"},"quadAppArea:B4":{"question":"一段长为 30 m 的墙 MN 前有一块矩形 ABCD 空地，用 100 m 长的篱笆围成如图所示的图形（靠墙的一边不用篱笆，篱笆的厚度忽略不计），其中四边形 AEFH 和四边形 CDHG 是矩形，四边形 EBGF 是边长为 10 m 的正方形，设 CD=x m。①若矩形 CDHG 面积为 125 m²，求 CD 长；②当 CD 长为多少米时，矩形 ABCD 的面积最大，最大面积是多少？","analysis":"由 EBGF 为边长 10 的正方形、AEFH 与 CDHG 为矩形，设 CD=x、AD=BC=w，则 DH=GC=w−10，HG=x，AE=FH=x−10｜—1分｜【得分理由：正确建立图形几何关系】\n篱笆总长=AB(x)+BC(w)+CD(x)+EF(10)+FG(10)+FH(x−10)+HG(x)=100，整理得 w=90−3x｜—1分｜【得分理由：正确列出篱笆长度约束】\n矩形 CDHG 面积=CD·DH=x(w−10)=x(80−3x)=125｜—1分｜【得分理由：正确列出面积方程】\n解得 3x²−80x+125=0，x=25 或 x=5/3；x=5/3 时 w=85>30 超墙长，舍去｜—1分｜【得分理由：正确解方程并按墙长取舍】\n故 CD=25 m｜—1分｜【得分理由：正确作答第①问】\n矩形 ABCD 面积 S=x·w=x(90−3x)，墙长限 w≤30 得 x≥20，且 w>0 得 x<30｜—1分｜【得分理由：正确建立面积函数与定义域】\n对称轴 x=15 不在区间 [20,30) 内，开口向下，故 S 在 [20,30) 上递减｜—1分｜【得分理由：正确判断区间单调性】\n故 x=20 时 Smax=20×(90−60)=600 m²｜—1分｜【得分理由：正确得出最大面积并作答】\n（进化点：复合图形（正方形+两矩形），先由篱笆约束求中间量 w=90−3x，再列面积函数求最值；注意正方形顶点为 EBGF 而非 EFGH）","questionImage":"images/area_复合图形.png"},"quadAppGraph:B4":{"question":"公路上正在行驶的甲车，发现前方 20 m 处有同一方向行驶的乙车后，开始减速，减速后甲车行驶的路程 s（单位：m）、速度 v（单位：m/s）与时间 t（单位：s）的关系分别可以用二次函数和一次函数表示，其图象如图所示（s-t 曲线过 (0,0)、(1,15.5)、(2,30)、(3,43.5)、(4,56)；v-t 直线过 (0,16)、(8,8)）。①当甲车减速至 9 m/s 时，它行驶的路程是多少？②若乙车以 10 m/s 的速度匀速行驶，两车何时相距最近，最近距离是多少？","analysis":"①由 v=−t+16，令 v=9，得 t=7｜—1分｜【得分理由：正确求出减速时间】\n①代入 s=−t²/2+16t，得 s(7)=175/2=87.5 m｜—1分｜【得分理由：正确计算路程】\n②乙车行驶 10t m，两车相距 d=20+10t−s=t²/2−6t+20｜—1分｜【得分理由：正确建立距离函数】\n②d 的对称轴为 t=6，开口向上，故 t=6 s 时两车相距最近｜—1分｜【得分理由：正确求最值点】\n②最近距离 d(6)=36/2−36+20=2 m｜—1分｜【得分理由：正确得出最近距离】\n（进化点：双图象（二次+一次）+运动综合，读两图并建立相对距离函数）","questionImage":"images/graph_甲车.png"},"extremeA:R0":{"question":"求函数 f(x)=x³−3x 的极值。","analysis":"f′(x)=3x²−3=3(x−1)(x+1)｜ —1分 ｜【得分理由：正确求导并因式分解】\n令 f′(x)=0，得 x=−1 或 x=1｜ —1分 ｜【得分理由：正确求出驻点】\nx<−1 时 f′(x)>0，f(x) 单调递增；−1<x<1 时 f′(x)<0，f(x) 单调递减；x>1 时 f′(x)>0，f(x) 单调递增｜ —1分 ｜【得分理由：正确判断单调性】\n∴ x=−1 处左正右负为极大值点，极大值 f(−1)=2；x=1 处左负右正为极小值点，极小值 f(1)=−2｜ —1分 ｜【得分理由：正确写出极值结论】\n（进化点：这是“求极值”的课本母题——求导→因式分解→判号→写极值，无参数、无超越函数、入口直接。）"},"extremeA:A1":{"question":"已知函数 f(x)=x³−3x+a 的极小值为 6，则实数 a 的值为（　）A．8　B．6　C．4　D．2","analysis":"f′(x)=3x²−3=3(x−1)(x+1)｜ —1分 ｜【得分理由：正确求导并因式分解】\n令 f′(x)=0，得 x=−1 或 x=1｜ —1分 ｜【得分理由：正确求出驻点】\nx<−1 时 f′(x)>0，−1<x<1 时 f′(x)<0，x>1 时 f′(x)>0，故 x=−1 为极大值点、x=1 为极小值点｜ —1分 ｜【得分理由：正确判断单调性并确定极值点】\n极小值 f(1)=1−3+a=a−2｜ —1分 ｜【得分理由：正确计算极小值的表达式】\n由题意 a−2=6，解得 a=8，故选 A｜ —1分 ｜【得分理由：由已知极值正确反求参数】\n（进化点：具体→参数——常数项变为参数 a（平移不改变极值点），目标反转为由已知极值反求参数。）"},"extremeA:A2":{"question":"已知函数 f(x)=(x−lnx)/x（x>0），求函数 f(x) 的极值。","analysis":"先化简：f(x)=x/x−lnx/x=1−lnx/x｜ —1分 ｜【得分理由：正确化简分式结构】\n求导（商的求导法则）：f′(x)=−[(1/x)·x−lnx·1]/x²=−(1−lnx)/x²=(lnx−1)/x²｜ —1分 ｜【得分理由：商法则应用正确】\n令 f′(x)=0，得 lnx=1，即 x=e｜ —1分 ｜【得分理由：正确求出驻点】\n0<x<e 时 f′(x)<0，f(x) 单调递减；x>e 时 f′(x)>0，f(x) 单调递增｜ —1分 ｜【得分理由：正确判断单调性】\n∴ x=e 处左减右增为极小值点，极小值 f(e)=1−ln e/e=1−1/e；无极大值｜ —1分 ｜【得分理由：正确写出极值结论】\n（进化点：单知识点→组合——叠加对数商式结构，新增“先化简再求导（商法则）”环节。）"},"extremeA:A3":{"question":"已知函数 f(x)=−2lnx+5x−x²，证明：f(x) 有两个不同的极值点。","analysis":"定义域为 x>0；f′(x)=−2/x+5−2x=(−2+5x−2x²)/x=−(2x−1)(x−2)/x｜ —1分 ｜【得分理由：正确求导并通分因式分解】\n令 f′(x)=0，得 x=1/2 或 x=2｜ —1分 ｜【得分理由：正确求出驻点】\nx>0 时分母恒正：0<x<1/2 时 (2x−1)(x−2)>0，f′(x)<0，f(x) 单调递减｜ —1分 ｜【得分理由：正确判断第一段单调性】\n1/2<x<2 时 (2x−1)(x−2)<0，f′(x)>0，f(x) 单调递增；x>2 时 f′(x)<0，f(x) 单调递减｜ —1分 ｜【得分理由：正确判断其余区间单调性】\n∴ x=1/2 处左负右正为极小值点，x=2 处左正右负为极大值点，f(x) 恰有两个不同的极值点，证毕｜ —1分 ｜【得分理由：由导数变号正确证出极值点个数】\n（进化点：单知识点→组合——叠加二次多项式与对数组合，目标由求极值变为证明极值点个数（变号论证）。）"},"extremeA:A4":{"question":"已知函数 f(x)=(ax+b)e^x 的图象在点 (0,f(0)) 处的切线方程为 2x−y+1=0。（1）求 a，b 的值；（2）求 f(x) 的单调区间与极值。","analysis":"（1）切线方程 2x−y+1=0 化为 y=2x+1，得切线斜率 2，且切点 (0,f(0)) 在切线上，故 f(0)=1｜ —1分 ｜【得分理由：正确提取切线斜率与切点纵坐标】\nf(0)=b·e⁰=b，所以 b=1｜ —1分 ｜【得分理由：由 f(0) 正确求出 b】\nf′(x)=ae^x+(ax+b)e^x=(ax+a+b)e^x，故 f′(0)=a+b｜ —1分 ｜【得分理由：正确求导并计算 f′(0)】\n由导数的几何意义 f′(0)=2，得 a+b=2，代入 b=1，解得 a=1｜ —1分 ｜【得分理由：正确求出 a】\n（2）f(x)=(x+1)e^x，f′(x)=(x+2)e^x；e^x>0 恒正｜ —1分 ｜【得分理由：正确代入并求导】\nx<−2 时 f′(x)<0，f(x) 单调递减；x>−2 时 f′(x)>0，f(x) 单调递增｜ —1分 ｜【得分理由：正确判断单调性】\n∴ 减区间为 (−∞,−2)，增区间为 (−2,+∞)；x=−2 处左减右增为极小值点，极小值 f(−2)=−1/e²；无极大值｜ —1分 ｜【得分理由：正确写出单调区间与极值】\n（进化点：条件显→隐——参数 a、b 藏于切线方程，新增“导数的几何意义+切点在切线上”环节。）"},"extremeB:R0":{"question":"求函数 f(x)=e^x−x 的极值。","analysis":"f′(x)=e^x−1｜ —1分 ｜【得分理由：正确求导】\n令 f′(x)=0，得 x=0（零点显式可解）｜ —1分 ｜【得分理由：正确求出显式零点】\nx<0 时 f′(x)<0，f(x) 单调递减；x>0 时 f′(x)>0，f(x) 单调递增｜ —1分 ｜【得分理由：正确判断单调性】\n∴ x=0 处左减右增为极小值点，极小值 f(0)=1；无极大值｜ —1分 ｜【得分理由：正确写出极值结论】\n（进化点：这是指数支母题——指数函数求导后零点显式、符号一目了然，无参数、无隐零点。）"},"extremeB:B1":{"question":"已知函数 f(x)=e^x−ax−a³，求函数 f(x) 的极值。","analysis":"f′(x)=e^x−a｜ —1分 ｜【得分理由：正确求导】\n当 a≤0 时，e^x>0≥a，f′(x)>0 在 R 上恒成立，f(x) 单调递增，无极值｜ —1分 ｜【得分理由：正确完成 a≤0 的分类讨论】\n当 a>0 时，令 f′(x)=0，得 x=ln a｜ —1分 ｜【得分理由：正确求出含参驻点】\nx<ln a 时 f′(x)<0，f(x) 单调递减；x>ln a 时 f′(x)>0，f(x) 单调递增｜ —1分 ｜【得分理由：正确判断单调性】\n∴ x=ln a 处左减右增为极小值点，极小值 f(ln a)=e^(ln a)−a·ln a−a³=a−a·ln a−a³；无极大值｜ —1分 ｜【得分理由：正确写出含参极值结论】\n（进化点：具体→参数——零点由常数 0 变为 ln a，新增按 a 的符号分类讨论环节（同函数 e^x−ax−a³ 的单调区间链见 monotoneExp:E01）。）"},"extremeB:B2":{"question":"已知函数 f(x)=e^x−x−lnx，定义域为 x∈(0,+∞)，求 f(x) 的极值点。","analysis":"f′(x)=e^x−1−1/x｜ —1分 ｜【得分理由：正确求导】\nf″(x)=e^x+1/x²>0，故 f′(x) 在 (0,+∞) 上单调递增｜ —1分 ｜【得分理由：正确证明 f′ 单调，为唯一零点做准备】\n估值判号：f′(1/2)=√e−3<0（√e≈1.65），f′(1)=e−2>0｜ —1分 ｜【得分理由：正确选取估值点并判号】\nf′(x) 连续且两端异号，由零点存在定理，存在唯一 x₀∈(1/2,1) 使 f′(x₀)=0（隐零点，不需解出）｜ —1分 ｜【得分理由：正确确定隐零点位置】\n0<x<x₀ 时 f′(x)<0，f(x) 单调递减；x>x₀ 时 f′(x)>0，f(x) 单调递增｜ —1分 ｜【得分理由：正确判断单调性】\n∴ x=x₀ 处左负右正为极小值点，无极大值点｜ —1分 ｜【得分理由：正确写出极值点结论】\n（进化点：加中间量——零点无法显式解出，先证 f′ 单调+零点存在定理确定隐零点 x₀ 的位置（同函数 e^x−x−lnx 的单调区间链见 monotoneExp:E02）。）"},"ssa:B1":{"question":"在△ABC中，b=10，A=π/6，若△ABC有唯一解，求 a 的取值范围。","analysis":"由正弦定理 sinB/b=sinA/a，得 sinB=b·sinA/a=10×sin(π/6)/a=5/a ｜ —1分 ｜ 【得分理由：用正弦定理表示 sinB】\n唯一解情形一：a=b·sinA=10×1/2=5，此时 sinB=1，B=π/2，直角三角形唯一解 ｜ —1分 ｜ 【得分理由：直角情形恰有一解】\n唯一解情形二：a≥b=10，此时 sinB=5/a≤1/2，B≤π/6（B≥5π/6 将与 A=π/6 使内角和超过 π，舍去），B 唯一 ｜ —1分 ｜ 【得分理由：大边情形恰有一解】\n综上 a=5 或 a≥10 ｜ —1分 ｜ 【得分理由：合并两类结果】\n答：a 的取值范围为 a=5 或 a≥10 ｜ —1分 ｜ 【得分理由：完整作答】"},"ssa:B2":{"question":"在△ABC中，A=30°，a=3，若三角形有两解，求 b 的取值范围。","analysis":"SSA 两解判定条件：b·sinA<a<b ｜ —1分 ｜ 【得分理由：写出两解判定条件】\n代入 A=30°、a=3：b×sin30°<3<b ｜ —1分 ｜ 【得分理由：代入已知量】\nsin30°=1/2，解 b/2<3 得 b<6，解 3<b 得 b>3 ｜ —1分 ｜ 【得分理由：解不等式组】\n∴ b 的取值范围为 3<b<6 ｜ —1分 ｜ 【得分理由：写出最终范围】"},"ssa:B3":{"question":"在△ABC中，b=4，A=30°，当 C 有两解时，求 a 的取值范围。","analysis":"SSA 两解判定条件：b·sinA<a<b ｜ —1分 ｜ 【得分理由：写出两解判定条件】\n代入 b=4、A=30°：4×sin30°<a<4 ｜ —1分 ｜ 【得分理由：代入已知量】\nsin30°=1/2，化简得 2<a<4 ｜ —1分 ｜ 【得分理由：化简得范围】\n答：a 的取值范围为 2<a<4 ｜ —1分 ｜ 【得分理由：完整作答】\n（进化点：这一步只做“目标互换”（求 b→求 a），角度仍是直接给的。）"},"ssa:B4":{"question":"在△ABC中，b=4，tanA=√7/3，当 C 有两解时，求 a 的取值范围。","analysis":"由 tanA=√7/3 且 A 为三角形内角，取 A 为锐角 ｜ —1分 ｜ 【得分理由：由正切值确定角 A 为锐角】\n构造直角三角形：对边 √7、邻边 3、斜边 √(7+9)=4，得 sinA=√7/4 ｜ —1分 ｜ 【得分理由：由 tan 求 sin】\nSSA 两解判定条件：b·sinA<a<b ｜ —1分 ｜ 【得分理由：写出两解判定条件】\n代入 b=4、sinA=√7/4：4×√7/4<a<4 ｜ —1分 ｜ 【得分理由：代入已知量】\n∴ √7<a<4 ｜ —1分 ｜ 【得分理由：化简得最终范围】"}};
